}

impl<P: Send + Sync + 'static> ReturnedSnapshotReadRetirement<P> {
    fn new(alias: Arc<P>, owned_factory: Arc<dyn ArtifactOwnedValueRetirementFactory<P>>) -> Self {
        Self { alias: std::mem::ManuallyDrop::new(Some(alias)), unique: std::mem::ManuallyDrop::new(None), owned_factory }
    }
}

impl<P: Send + Sync + 'static> ErasedSnapshotRetirement for ReturnedSnapshotReadRetirement<P> {
    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(unique) = self.unique.as_mut() {
            return match unique.close_step(maximum_items, maximum_bytes)? {
                SnapshotRetirementStep::Complete if unique.terminal_is_empty() => {
                    drop(self.unique.take());
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
                SnapshotRetirementStep::Complete => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "returned snapshot read unique owner reported Complete without terminal-empty authority")),
                step => Ok(step),
            };
        }
        let Some(alias) = self.alias.take() else { return Ok(SnapshotRetirementStep::Complete) };
        match Arc::into_inner(alias) {
            Some(unique) => {
                *self.unique = Some(self.owned_factory.retire_owned(unique));
                Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 })
            }
            None => Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 }),
        }
    }

    fn terminal_is_empty(&self) -> bool {
        self.alias.is_none() && self.unique.is_none()
    }

    /// 📏️ Forwarded from the owner this retirement is currently spending: once `Arc::into_inner`
    /// has handed the value to its owned-value disposer, THAT disposer's demand is this one's. The
    /// alias phase itself costs no bytes.
    fn next_close_byte_demand(&self) -> usize {
        self.unique.as_ref().map_or(1, |unique| unique.next_close_byte_demand())
    }
}

impl<P: Send + Sync + 'static> Drop for ReturnedSnapshotReadRetirement<P> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "returned snapshot read retired before terminal-empty ownership");
    }
}

fn advance_returned_snapshot_read<P: Send + Sync + 'static>(
    registry: &SnapshotReadLeaseRegistry,
    active: &mut Option<Box<dyn ErasedSnapshotRetirement>>,
    factory: &Arc<dyn ArtifactOwnedValueRetirementFactory<P>>,
    maximum_items: usize,
    maximum_bytes: usize,
) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
    if maximum_items == 0 {
        return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
    }
    if let Some(owner) = active.as_mut() {
        return match owner.close_step(maximum_items.min(1), maximum_bytes)? {
            SnapshotRetirementStep::Complete if owner.terminal_is_empty() => {
                drop(active.take());
                Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
            }
            SnapshotRetirementStep::Complete => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "returned transient read completed without its exact empty witness")),
            SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items > 1 || released_bytes > maximum_bytes => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "returned transient read exceeded its exact grant")),
            step => Ok(step),
        };
    }
    if !registry.has_returned() {
        return Ok(SnapshotRetirementStep::Complete);
    }
    match registry.try_take_one_returned::<P>() {
        Ok(Some(root)) => {
            *active = Some(Box::new(ReturnedSnapshotReadRetirement::new(root, factory.clone())));
            Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
        }
        Ok(None) => Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 }),
        Err(SnapshotReadLeaseRefusal::Busy) => Ok(SnapshotRetirementStep::Blocked),
        Err(reason) => Err(reason.into_value_error()),
    }
}

const ARTIFACT_STORE_DISPLACED_RETIREMENT_CAPACITY: usize = 1_024;
const ARTIFACT_STORE_DISPLACED_RESERVATION_CAPACITY: usize = 8;
/// 🌡️ Displaced-owner occupancy at which a store reports maintenance PRESSURE — a quarter of the
/// fixed queue. Every commit displaces its envelope, current snapshot and dag (three owners, more
/// with a tail undo entry) and the round-robin maintenance pump drains ONE owner step per visit, so
/// a live cadence of coalesced commits (a playback tick, a gumball drag step) fills the queue a
/// hundred times faster than the fair rotation empties it. Above this mark the host drains the
/// pressured queue out of turn and in bursts until it is back under.
pub const ARTIFACT_STORE_DISPLACED_PRESSURE_OCCUPANCY: usize = ARTIFACT_STORE_DISPLACED_RETIREMENT_CAPACITY / 4;

struct ArtifactStoreDisplacedRetirements {
    owners: std::mem::ManuallyDrop<VecDeque<Box<dyn ErasedSnapshotRetirement>>>,
    owner_reservations: [Option<(u64, usize)>; ARTIFACT_STORE_DISPLACED_RESERVATION_CAPACITY],
    owner_generation: u64,
}

struct ArtifactStoreDisplacedOwnerReservation {
    slot: u8,
    generation: u64,
    remaining: usize,
}

impl ArtifactStoreDisplacedRetirements {
    fn new() -> Self {
        Self {
            owners: std::mem::ManuallyDrop::new(VecDeque::with_capacity(ARTIFACT_STORE_DISPLACED_RETIREMENT_CAPACITY)),
            owner_reservations: [None; ARTIFACT_STORE_DISPLACED_RESERVATION_CAPACITY],
            owner_generation: 0,
        }
    }

    fn reserve(&self, count: usize) -> Result<(), VcsError> {
        let occupied = self
            .owners
            .len()
            .checked_add(self.owner_reservations.iter().flatten().map(|(_, count)| *count).sum::<usize>())
            .ok_or_else(|| VcsError::ValidationFailed("artifact store displaced-owner occupancy overflowed".into()))?;
        if count > ARTIFACT_STORE_DISPLACED_RETIREMENT_CAPACITY.saturating_sub(occupied) {
            return Err(VcsError::ValidationFailed("artifact store displaced-owner fixed retirement authority is saturated".into()));
        }
        Ok(())
    }

    fn reserve_owner_slots(&mut self, count: usize) -> Result<ArtifactStoreDisplacedOwnerReservation, VcsError> {
        if count == 0 {
            return Err(VcsError::ValidationFailed("artifact store displaced-owner reservation is empty".into()));
        }
        let slot = self.owner_reservations.iter().position(Option::is_none).ok_or_else(|| VcsError::ValidationFailed("artifact store displaced-owner reservation registry is saturated".into()))?;
        self.reserve(count)?;
        let generation = self.owner_generation.checked_add(1).ok_or_else(|| VcsError::ValidationFailed("artifact store displaced-owner reservation generation exhausted".into()))?;
        self.owner_generation = generation;
        self.owner_reservations[slot] = Some((generation, count));
        Ok(ArtifactStoreDisplacedOwnerReservation { slot: slot as u8, generation, remaining: count })
    }

    fn push_owner_reserved(&mut self, reservation: &mut ArtifactStoreDisplacedOwnerReservation, owner: Box<dyn ErasedSnapshotRetirement>) -> Result<(), Box<dyn ErasedSnapshotRetirement>> {
        let slot = reservation.slot as usize;
        if reservation.remaining == 0 || self.owner_reservations.get(slot).copied().flatten() != Some((reservation.generation, reservation.remaining)) || self.owners.len() >= ARTIFACT_STORE_DISPLACED_RETIREMENT_CAPACITY {
            return Err(owner);
        }
        reservation.remaining -= 1;
        self.owner_reservations[slot] = (reservation.remaining != 0).then_some((reservation.generation, reservation.remaining));
        self.owners.push_back(owner);
        Ok(())
    }

    fn release_owner_slots(&mut self, reservation: ArtifactStoreDisplacedOwnerReservation) -> Result<(), VcsError> {
        if reservation.remaining == 0 {
            if self.owner_reservations[reservation.slot as usize].is_some_and(|(generation, _)| generation == reservation.generation) {
                return Err(VcsError::ValidationFailed("artifact store consumed displaced-owner reservation retained live credits".into()));
            }
            return Ok(());
        }
        if self.owner_reservations[reservation.slot as usize] != Some((reservation.generation, reservation.remaining)) {
            return Err(VcsError::ValidationFailed("artifact store displaced-owner reservation is stale or partially consumed".into()));
        }
        self.owner_reservations[reservation.slot as usize] = None;
        Ok(())
    }

    fn push_reserved(&mut self, owner: Box<dyn ErasedSnapshotRetirement>) {
        let reserved = self.owner_reservations.iter().flatten().map(|(_, count)| *count).sum::<usize>();
        assert!(self.owners.len() < ARTIFACT_STORE_DISPLACED_RETIREMENT_CAPACITY.saturating_sub(reserved), "artifact store displaced-owner admission token was consumed after its fixed slot changed");
        self.owners.push_back(owner);
    }

    fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        let Some(owner) = self.owners.front_mut() else {
            return if self.owner_reservations.iter().any(Option::is_some) { Ok(SnapshotRetirementStep::Blocked) } else { Ok(SnapshotRetirementStep::Complete) };
        };
        match owner.close_step(maximum_items, maximum_bytes)? {
            SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(SnapshotRetirementStep::Pending { released_items, released_bytes }),
            SnapshotRetirementStep::Pending { .. } => Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "artifact store displaced owner exceeded its exact item or byte grant")),
            SnapshotRetirementStep::Blocked => Ok(SnapshotRetirementStep::Blocked),
            SnapshotRetirementStep::Complete => {
                if !owner.terminal_is_empty() {
                    return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "artifact store displaced owner reported Complete without its exact terminal-empty witness"));
                }
                let owner = self.owners.pop_front().expect("validated displaced owner remains present");
                drop(owner);
                Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
            }
        }
    }

    fn terminal_is_empty(&self) -> bool {
        self.owners.is_empty() && self.owner_reservations.iter().all(Option::is_none)
    }

    /// 🔭️ Why this queue is not terminal — a queued owner the closer is draining, or a RESERVED
    /// slot no owner ever filled. The two answer `Blocked` from the same arm and need different
    /// cures, so the census names them apart.
    fn witness(&self) -> String {
        let reserved = self.owner_reservations.iter().flatten().map(|(_, count)| *count).sum::<usize>();
        format!("owners={}/reserved={}", self.owners.len(), reserved)
    }

    fn under_pressure(&self) -> bool {
        self.owners.len() >= ARTIFACT_STORE_DISPLACED_PRESSURE_OCCUPANCY
    }
}

impl Drop for ArtifactStoreDisplacedRetirements {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "artifact store displaced-owner authority reached Drop before bounded retirement completed");
        let owners = unsafe { std::mem::ManuallyDrop::take(&mut self.owners) };
        drop(owners);
    }
}

