        let (record, _report) = decode_document(bytes, &value_bridge_spec(), &PackDecodeOptions::default())?;
        match record.get(VALUE_BRIDGE_FIELD_ID) {
            Some(FieldValue::Value(dsl_value)) => Ok(dsl_value.clone()),
            _ => Ok(DslValue::Null),
        }
    }

