    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum PeerRosterPublicationStage {
        DecodeMetadata,
        PruneTyped,
        DecodeTyped,
        ReleaseCreated,
        Ready,
    }

    /// 📦️ Fixed slots retaining each peer identity and its encoded presence.
    type PeerPresencePacks = [Option<(String, Vec<u8>)>; PEER_PRESENCE_SLOTS];

    pub(crate) struct PeerRosterPublication<A: ArtifactApp> {
        seq: u64,
        generation: u64,
        own_color: Option<u8>,
        now_ms: i64,
        cancel: semio_framework_job::CancelToken,
        raw: protocol::PresenceCommandCursor,
        candidate: std::mem::ManuallyDrop<Option<PeerPresenceRoot>>,
        retirement: std::mem::ManuallyDrop<Option<PeerPresenceRootRetirement>>,
        packs: std::mem::ManuallyDrop<PeerPresencePacks>,
        packs_len: usize,
        packs_shell_released: bool,
        typed: std::mem::ManuallyDrop<Option<store::PresencePeersPublication<A::Presence>>>,
        rejected: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
        stage: PeerRosterPublicationStage,
        faulted: bool,
        fault: Option<Fault>,
    }

    impl<A: ArtifactApp> PeerRosterPublication<A> {
        fn new(admission: PresenceRosterAdmission, now_ms: i64, raw: protocol::PresenceCommandCursor) -> Self {
            Self {
                seq: admission.seq,
                generation: admission.generation,
                own_color: raw.own_color(),
                now_ms,
                cancel: admission.cancel,
                raw,
                candidate: std::mem::ManuallyDrop::new(Some(PeerPresenceRoot::empty())),
                retirement: std::mem::ManuallyDrop::new(None),
                packs: std::mem::ManuallyDrop::new(std::array::from_fn(|_| None)),
                packs_len: 0,
                packs_shell_released: false,
                typed: std::mem::ManuallyDrop::new(None),
                rejected: std::mem::ManuallyDrop::new(None),
                stage: PeerRosterPublicationStage::DecodeMetadata,
                faulted: false,
                fault: None,
            }
        }

        fn fail(&mut self, fault: Fault) -> PluginCloseStep {
            self.faulted = true;
            if self.fault.is_none() {
                self.fault = Some(fault);
            }
            PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }
        }

        fn rejected(admission: PresenceRosterAdmission, raw: FixedCommandPage, fault: Fault) -> Self {
            let seq = admission.seq;
            let mut publication = Self::new(admission, 0, protocol::PresenceCommandCursor::retain_rejected(raw, seq));
            publication.fail(fault);
            publication
        }

        #[expect(clippy::result_large_err, reason = "Refusal returns the original fixed-capacity input so its caller can retry or retire that exact owner without an extra allocation.")]
        fn push_page(&mut self, page_index: u32, page: FixedCommandPage) -> Result<(), (Fault, FixedCommandPage)> {
            self.raw.push_page(page_index, page).map_err(|(error, page)| (error.into_fault(), page))
        }

        /// 🥡️ SAFETY: every owned pack was transferred or released in a bounded step and this
        /// exact flag makes the fixed empty shell release once.
        fn release_packs_shell(&mut self) {
            if !self.packs_shell_released {
                debug_assert_eq!(self.packs_len, 0);
                unsafe { std::mem::ManuallyDrop::drop(&mut self.packs) };
                self.packs_shell_released = true;
            }
        }

        fn step(&mut self, presence_store: &store::PresenceStore<A::Presence, A::PresenceMutation>, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if ::semio_framework_async::poll::resolve_ready(self.cancel.is_cancelled()) {
                return Ok(self.fail(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-cancelled"), "peer roster publication was cancelled before commit")));
            }
            match self.stage {
                PeerRosterPublicationStage::DecodeMetadata => {
                    if self.raw.terminal_is_empty() {
                        *self.typed = Some(presence_store.begin_peer_publication().map_err(|error| plugin_sdk_fault(error.to_string()))?);
                        self.stage = PeerRosterPublicationStage::PruneTyped;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                    if self.raw.waiting_for_page() {
                        return Ok(PluginCloseStep::Blocked { reason: "peer roster publication is waiting for its next exact page owner" });
                    }
                    let next_len = match self.raw.next_len() {
                        Ok(next_len) => next_len,
                        Err(error) => return Ok(self.fail(plugin_sdk_fault(error.to_string()))),
                    };
                    let Some(next_len) = next_len else {
                        let (complete, released_bytes) = self.raw.close_release(maximum_bytes);
                        return Ok(PluginCloseStep::Pending { released_items: usize::from(complete), released_bytes });
                    };
                    if next_len > maximum_bytes {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    let raw = match self.raw.take_next() {
                        Ok(Some(raw)) => raw,
                        Ok(None) => unreachable!("presence cursor advertised one retained entry"),
                        Err(error) => return Ok(self.fail(plugin_sdk_fault(error.to_string()))),
                    };
                    let bytes = raw.len();
                    let decoded = ::semio_framework_async::poll::resolve_ready(protocol::decode_presence_peer(raw.as_slice()));
                    match decoded {
                        Ok(peer) => {
                            let protocol::PresencePeer { actor, presence_pack, color, surface, interaction, .. } = peer;
                            let pack_actor = presence_pack.as_ref().map(|_| actor.clone());
                            if let Err(fault) = self
                                .candidate
                                .as_mut()
                                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-candidate"), "peer roster candidate was already transferred"))?
                                .insert(actor, PeerPresence { color, surface, interaction })
                            {
                                return Ok(self.fail(fault));
                            }
                            if let (Some(actor), Some(pack)) = (pack_actor, presence_pack) {
                                if pack.len() > PEER_ROSTER_WIRE_BYTES || self.packs_len == PEER_PRESENCE_SLOTS {
                                    return Ok(self.fail(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-presence-pack-cap"), "one app-typed presence pack exceeds its fixed decode authority")));
                                }
                                self.packs[self.packs_len] = Some((actor, pack));
                                self.packs_len += 1;
                            }
                        }
                        Err(error) => return Ok(self.fail(plugin_sdk_fault(error.to_string()))),
                    }
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes })
                }
                PeerRosterPublicationStage::PruneTyped => {
                    let root = self.candidate.as_ref().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-candidate"), "peer roster metadata candidate was already transferred"))?;
                    let progressed = self
                        .typed
                        .as_mut()
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-candidate"), "app-typed peer candidate was not initialized"))?
                        .prune_one(|actor| root.contains_key(actor))
                        .map_err(|error| plugin_sdk_fault(error.to_string()))?;
                    if !progressed {
                        self.stage = PeerRosterPublicationStage::DecodeTyped;
                    }
                    Ok(PluginCloseStep::Pending { released_items: usize::from(progressed), released_bytes: 0 })
                }
                PeerRosterPublicationStage::DecodeTyped => {
                    if self.packs_len == 0 {
                        self.release_packs_shell();
                        self.stage = PeerRosterPublicationStage::ReleaseCreated;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                    let (_actor, pack) = self.packs[self.packs_len - 1].as_ref().expect("retained app-typed presence pack");
                    if pack.len() > maximum_bytes {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    let (actor, pack) = self.packs[self.packs_len - 1].take().expect("retained app-typed presence pack");
                    self.packs_len -= 1;
                    let bytes = pack.len();
                    let presence = match A::Presence::decode_pack(&pack) {
                        Ok(presence) => presence,
                        Err(error) => {
                            return Ok(self.fail(plugin_sdk_fault(error.to_string())));
                        }
                    };
                    drop(pack);
                    let typed = self.typed.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-candidate"), "app-typed peer candidate was already transferred"))?;
                    if let Err(rejected) = typed.adopt(actor, presence, self.now_ms) {
                        let reason = rejected.reason;
                        *self.rejected = Some(rejected.into_retirement());
                        return Ok(self.fail(plugin_sdk_fault(reason)));
                    }
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes })
                }
                PeerRosterPublicationStage::ReleaseCreated => {
                    let released = self.typed.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-candidate"), "app-typed peer candidate was already transferred"))?.release_created_one();
                    if !released {
                        self.stage = PeerRosterPublicationStage::Ready;
                    }
                    Ok(PluginCloseStep::Pending { released_items: usize::from(released), released_bytes: 0 })
                }
                PeerRosterPublicationStage::Ready => Ok(PluginCloseStep::Complete),
            }
        }

        fn take_candidate(&mut self) -> Result<PeerRosterCandidate<A::Presence>, Fault> {
            if self.faulted || self.stage != PeerRosterPublicationStage::Ready || !self.raw.terminal_is_empty() || !self.packs_shell_released {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-not-ready"), "peer roster candidate was requested before every retained stage completed"));
            }
            let metadata = self.candidate.take().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-candidate"), "peer roster metadata candidate was already transferred"))?;
            let typed = match self.typed.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-candidate"), "app-typed peer candidate was already transferred"))?.take_commit() {
                Ok(typed) => typed,
                Err(error) => {
                    *self.candidate = Some(metadata);
                    return Err(plugin_sdk_fault(error));
                }
            };
            let typed_shell = self.typed.take().expect("terminal app-typed peer candidate");
            assert!(typed_shell.terminal_is_empty(), "take_commit consumes every app-typed publication owner before its shell is released");
            drop(typed_shell);
            let root = std::sync::Arc::new(metadata);
            Ok(PeerRosterCandidate { seq: self.seq, generation: self.generation, cancel: self.cancel.clone(), own_color: self.own_color, now_ms: self.now_ms, root, typed })
        }

        fn retain_rejected_candidate(&mut self, candidate: PeerRosterCandidate<A::Presence>) {
            assert!(self.terminal_is_empty(), "returned peer candidate must rejoin its exact empty publication owner");
            *self.retirement = Some(PeerPresenceRootRetirement::new(candidate.root));
            *self.rejected = Some(Box::new(candidate.typed.into_retirement()));
            self.fail(plugin_sdk_fault("presence peer publication lost its exact live base or factory authority"));
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(retirement) = self.retirement.as_mut() {
                let step = retirement.close_step(maximum_items, maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !retirement.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-terminal-not-empty"), "peer roster candidate retirement reported Complete without an empty terminal witness"));
                }
                drop(self.retirement.take());
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(rejected) = self.rejected.as_mut() {
                return match rejected.close_step(maximum_items, maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))? {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    store::SnapshotRetirementStep::Pending { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-rejected-over-budget"), "rejected app-typed presence disposer exceeded its exact grant")),
                    store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "rejected app-typed presence remains externally owned" }),
                    store::SnapshotRetirementStep::Complete => {
                        if !rejected.terminal_is_empty() {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-rejected-terminal-not-empty"), "rejected app-typed presence disposer reported Complete without an empty terminal witness"));
                        }
                        drop(self.rejected.take());
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                };
            }
            if !self.raw.terminal_is_empty() {
                let (complete, released_bytes) = self.raw.close_release(maximum_bytes);
                return Ok(PluginCloseStep::Pending { released_items: usize::from(complete), released_bytes });
            }
            if self.packs_len != 0 {
                let (_, pack) = self.packs[self.packs_len - 1].as_ref().expect("retained app-typed presence close pack");
                if pack.len() > maximum_bytes {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                let (_, pack) = self.packs[self.packs_len - 1].take().expect("retained app-typed presence close pack");
                self.packs_len -= 1;
                let bytes = pack.len();
                drop(pack);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes });
            }
            self.release_packs_shell();
            if let Some(root) = self.candidate.take() {
                *self.retirement = Some(PeerPresenceRootRetirement::new(std::sync::Arc::new(root)));
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(typed) = self.typed.as_mut() {
                let step = typed.close_step(maximum_items, maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))?;
                if step != store::SnapshotRetirementStep::Complete {
                    return Ok(match step {
                        store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => PluginCloseStep::Pending { released_items, released_bytes },
                        store::SnapshotRetirementStep::Pending { .. } => {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-over-budget"), "app-typed peer candidate cleanup exceeded its exact grant"));
                        }
                        store::SnapshotRetirementStep::Blocked => PluginCloseStep::Blocked { reason: "app-typed peer candidate cleanup remains externally blocked" },
                        store::SnapshotRetirementStep::Complete => unreachable!(),
                    });
                }
                if !typed.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.peer-roster-typed-terminal-not-empty"), "app-typed peer candidate cleanup reported Complete without its exact terminal witness"));
                }
                drop(self.typed.take());
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(PluginCloseStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.raw.terminal_is_empty() && self.packs_shell_released && self.candidate.is_none() && self.retirement.is_none() && self.typed.is_none() && self.rejected.is_none()
        }
    }

    impl<A: ArtifactApp> Drop for PeerRosterPublication<A> {
        fn drop(&mut self) {
            debug_assert!(std::thread::panicking() || self.terminal_is_empty(), "incomplete peer roster publication reached Drop without bounded disposal");
        }
    }

    /// 👥️ One peer's mark on a single interaction target — `InteractionView::peers_selecting`/
    /// `peers_hovering`'s element type (contract-freeze §C7.6), sorted by actor.
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub struct PeerMark<'a> {
        pub actor: &'a str,
        pub color: Option<u8>,
    }

    /// 🈳️ Lazily-initialized empty fallbacks `InteractionView`'s accessors return for an undeclared or
    /// never-touched domain — one static pair shared across every instance, so the accessor methods
    /// below can return a plain `&DomainSelection`/`&DomainHover` (no `Option`, no per-call allocation)
    /// exactly like the ticket's specified signature.
    // 🚫️async: E1-adjacent pure lazily-initialized static accessor consumed by `unwrap_or_else`/
    // `match`'s sync arms in `InteractionView::selection`/`hover` — see R9.
    fn empty_domain_selection() -> &'static protocol::DomainSelection {
        static EMPTY: std::sync::OnceLock<protocol::DomainSelection> = std::sync::OnceLock::new();
        EMPTY.get_or_init(protocol::DomainSelection::default)
    }

    // 🚫️async: E1-adjacent pure lazily-initialized static accessor consumed by `unwrap_or_else`/
    // `match`'s sync arms in `InteractionView::selection`/`hover` — see R9.
    fn empty_domain_hover() -> &'static protocol::DomainHover {
        static EMPTY: std::sync::OnceLock<protocol::DomainHover> = std::sync::OnceLock::new();
        EMPTY.get_or_init(protocol::DomainHover::default)
    }

    /// 🈳️ The draft references of a view no time-travel draft feeds — a dispatch, presence stamping, a viewer law.
    pub(crate) fn empty_draft_references() -> &'static std::collections::BTreeMap<String, Vec<String>> {
        static EMPTY: std::collections::BTreeMap<String, Vec<String>> = std::collections::BTreeMap::new();
        &EMPTY
    }

    /// 🧮️ The ONE flat projection of an `InteractionState`'s selection half: every domain's ids as a
    /// SET — each topology id at most once, in first-seen domain order. A selection is a set of
    /// topology ids, so the flattened publication must be one too: `overlay_leftover_ids_into_vortex`
    /// deliberately republishes another domain's ids under a second `vortex` key, so a plain flatten
    /// reports a single pick once per mirroring domain. Measured live on 2026-09-12 (ticket
    /// 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️selection-dedupe-2026-09-12.md`): one click on the
    /// generation3d preview published `selectedIds: ["extrude@solid","extrude@solid"]` while `locked`
    /// — an object, so keyed by construction — carried the id exactly once.
    // 🚫️async: E1 pure fold over an owned map, consumed by `InteractionView::leftover_selected_ids`
    // and `leftover_interaction_view_from`'s sync bodies — see R9.
    pub(crate) fn leftover_selected_ids_of(state: &protocol::InteractionState) -> Vec<String> {
        let mut ids: Vec<String> = Vec::new();
        for selection in state.selection.values() {
            for id in &selection.ids {
                if !ids.iter().any(|existing| existing == id) {
                    ids.push(id.clone());
                }
            }
        }
        ids
    }

    /// 🧲️ Leftover `interactionView.gumball.active` — always false. Selection leftovers exist so
    /// Inspection/outliner/gumball-target consumers see ids before the guest lane repaints; arming the
    /// world gumball is app-authored on the guest `selectionJson` lane (`gumballActive` +
    /// `transformMode` keyed off the armed utility), never inferred from bare selected ids (puzzle3d
    /// ticket 26/08/14/FIRST-CLASS-HOVER-AND-SELECTION-MECHANISM).
    pub(crate) fn leftover_gumball_active_v1() -> bool {
        false
    }

    /// 🕹️ Read-only view of the framework-owned INTERACTION mechanism (hover + selection + active
    /// mode/granularity per domain) — threaded into `ArtifactApp::handle`/`copy_fragment`/
    /// `cut_operations` so an app reads its own current selection/hover instead of ever storing it
    /// again itself. `state` is the persisted-local half (selection/mode/granularity, one
    /// `VcsArtifactApp::interaction_store` `ApplyInLane{lane: HistoryLane::Interaction}` dispatch away
    /// from every change); `hover` is the ephemeral-local half (`VcsArtifactApp::interaction_hover`,
    /// never persisted — see that field's own doc comment). Both are combined once per dispatch by
    /// `VcsArtifactApp::interaction_view`, never mutated through this read-only handle.
    pub struct InteractionView<'a> {
        pub(crate) state: &'a protocol::InteractionState,
        pub(crate) hover: &'a InteractionHoverState,
        /// 👥️ Every OTHER peer's last-adopted presence, keyed by actor — see
        /// `VcsArtifactApp::peer_presence`'s own doc comment. Sourced from `BTreeMap` iteration
        /// order, which is already sorted by actor.
        pub(crate) peers: &'a PeerPresenceRoot,
        /// ⏪️ What the open time-travel draft references, per selection domain
        /// ([`crate::time_travel::TimeTravelLedger::draft_references`]) — empty while no draft editor is open.
        pub(crate) draft_references: &'a std::collections::BTreeMap<String, Vec<String>>,
    }

    impl<'a> InteractionView<'a> {
        /// 🔗️ `domain`'s ids the open time-travel draft references — every id its `Reference` inputs of that domain
        /// hold, so a render highlights what the edited mutation acts on; empty while no draft editor is open.
        pub fn draft_references(&self, domain: &str) -> &[String] {
            self.draft_references.get(domain).map_or(&[], Vec::as_slice)
        }

        /// 🖱️ `domain`'s current selection — an empty `DomainSelection` (not `None`) for an undeclared
        /// or never-selected domain, so call sites never have to unwrap.
        pub fn selection(&self, domain: &str) -> &protocol::DomainSelection {
            self.state.selection.get(domain).unwrap_or_else(|| empty_domain_selection())
        }

        /// 🕹️ Leftover.ids for Inspection: every domain's selected ids as a SET (see
        /// {@link leftover_selected_ids_of}). A pick can land on leftover `selectedIds` while
        /// `selection(vortex)` is still the empty persist snapshot.
        pub fn leftover_selected_ids(&self) -> Vec<String> {
            leftover_selected_ids_of(self.state)
        }

        /// 🐁️ `domain`'s current hover on `channel` — empty when nothing is hovered on that channel
        /// right now. `InteractionState.hover` holds exactly one live channel per domain at a time (the
        /// most recently hovered — see `next_hover`'s doc), so a `channel` mismatch also reads empty
        /// rather than returning a stale different-channel hover.
        pub fn hover(&self, domain: &str, channel: &str) -> &protocol::DomainHover {
            match self.hover.get(domain) {
                Some(hover) if hover.channel == channel => hover,
                _ => empty_domain_hover(),
            }
        }

        /// 🪜️ `domain`'s active granularity id, `None` for an undeclared domain (never dispatched
        /// through `validate_state` yet — e.g. a registry-less test construction).
        pub fn active_granularity(&self, domain: &str) -> Option<&str> {
            self.state.active_granularity.get(domain).map(String::as_str)
        }

        /// 🔀️ `domain`'s active `SelectionMode`, `None` for an undeclared domain.
        pub fn active_mode(&self, domain: &str) -> Option<protocol::SelectionMode> {
            self.state.active_mode.get(domain).copied()
        }

        /// 👥️ Every OTHER peer currently selecting `id` within `domain`, sorted by actor
        /// (contract-freeze §C7.6) — `[]` for a peer with no adopted interaction, an interaction with
        /// no matching domain, or a domain where `id` is not in `selected`.
        /// 🚫️async: E1 pure in-memory filter, no suspension point — see R9.
        ///
        /// ⚠️ Gap (SEMANTIC-UI-CONTRACT-AND-RENDERER-FAMILY packet `sdk-helpers` — see
        /// `📓️terra-sdk-helpers-report.md`): the sync `marks_for` closure this used to feed
        /// (`stamp_and_cache_interaction_ui`'s old presence-stamping half) is gone — that destination no
        /// longer exists on a built node. This method itself is unaffected and still tested directly; a
        /// future packet publishing real `PresenceUpdate`s is the next intended caller.
        pub fn peers_selecting(&self, domain: &str, id: &str) -> Vec<PeerMark<'a>> {
            self.peers
                .iter()
                .filter_map(|(actor, presence)| {
                    let interaction = presence.interaction.as_ref()?;
                    let matched = interaction.domains.iter().find(|candidate| candidate.domain == domain)?;
                    matched.selected.iter().any(|selected_id| selected_id == id).then_some(PeerMark { actor, color: presence.color })
                })
                .collect()
        }

        /// 👥️ `peers_selecting`'s hover twin — every OTHER peer currently hovering `id` within
        /// `domain`, sorted by actor.
        /// 🚫️async: E1 pure in-memory filter — see `peers_selecting`'s doc for why this must be sync.
        pub fn peers_hovering(&self, domain: &str, id: &str) -> Vec<PeerMark<'a>> {
            self.peers
                .iter()
                .filter_map(|(actor, presence)| {
                    let interaction = presence.interaction.as_ref()?;
                    let matched = interaction.domains.iter().find(|candidate| candidate.domain == domain)?;
                    matched.hovered.iter().any(|hovered_id| hovered_id == id).then_some(PeerMark { actor, color: presence.color })
                })
                .collect()
        }
    }
