    /// 🧹️ Required disposal side of an app-owned persistent job. `Complete` is an assertion
    /// that dropping the concrete job immediately afterward is constant-time; no blanket/default
    /// implementation exists because an erased job may own arbitrarily deep snapshots or queues.
    pub trait ArtifactReservedJob: semio_framework_job::InteractiveJob {
        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault>;
        fn terminal_is_empty(&self) -> bool;
    }

    /// 📦️ Sized ActionBus payload around one app-owned concrete resumable state machine.
    struct ArtifactReservedToolJobState {
        /// 🧵️ `+ Send`: this state lives behind an `Arc<Mutex<…>>` the host moves across pool
        /// threads, so the box states the thread-transfer requirement itself now that
        /// `InteractiveJob` no longer imposes `Send` on single-threaded targets.
        inner: std::mem::ManuallyDrop<Option<Box<dyn ArtifactReservedJob + Send>>>,
        operation: Option<semio_framework_job::Operation>,
    }

    #[derive(Clone)]
    pub struct ArtifactReservedToolJob {
        state: std::sync::Arc<std::sync::Mutex<ArtifactReservedToolJobState>>,
    }

    impl ArtifactReservedToolJob {
        pub fn new<J: ArtifactReservedJob + Send + 'static>(job: J) -> Self {
            Self { state: std::sync::Arc::new(std::sync::Mutex::new(ArtifactReservedToolJobState { inner: std::mem::ManuallyDrop::new(Some(Box::new(job))), operation: None })) }
        }

        pub fn bind_operation(&mut self, operation: semio_framework_job::Operation) -> Result<(), semio_framework::ToolJobFactoryError> {
            let mut state = self.state.try_lock().map_err(|_| semio_framework::ToolJobFactoryError::new("reserved job operation authority is busy or poisoned"))?;
            if state.operation.is_some() {
                return Err(semio_framework::ToolJobFactoryError::new("reserved job operation authority was already bound"));
            }
            state.operation = Some(operation);
            Ok(())
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let mut state = self.state.try_lock().map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-close-busy"), "reserved job close authority is busy or poisoned"))?;
            let Some(inner) = state.inner.as_mut() else { return Ok(PluginCloseStep::Complete) };
            let step = ArtifactReservedJob::close_step(&mut **inner, maximum_items, maximum_bytes)?;
            if step == PluginCloseStep::Complete {
                if !ArtifactReservedJob::terminal_is_empty(&**inner) {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.reserved-terminal-not-empty"), "reserved job reported Complete without an exact terminal-empty witness"));
                }
                let terminal = state.inner.take();
                state.operation = None;
                drop(state);
                drop(terminal);
            }
            Ok(step)
        }

        fn terminal_is_empty(&self) -> bool {
            self.state.try_lock().is_ok_and(|state| state.inner.is_none() && state.operation.is_none())
        }

        fn begin_close(&mut self) {
            if let Ok(mut state) = self.state.try_lock() {
                if let Some(inner) = state.inner.as_mut() {
                    inner.begin_close();
                }
            }
        }
    }

    impl semio_framework_job::InteractiveJob for ArtifactReservedToolJob {
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            match self.state.try_lock() {
                Ok(mut state) => state.inner.as_mut().map_or(semio_framework_job::StepOutcome::Cancelled, |inner| inner.step(cx)),
                Err(std::sync::TryLockError::WouldBlock) => semio_framework_job::StepOutcome::Yield,
                Err(std::sync::TryLockError::Poisoned(_)) => {
                    semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, b"reserved job authority is poisoned") })
                }
            }
        }

        fn begin_close(&mut self) {
            ArtifactReservedToolJob::begin_close(self);
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            match ArtifactReservedToolJob::close_step(self, maximum_items, maximum_bytes) {
                Ok(PluginCloseStep::Pending { released_items, released_bytes }) => semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes },
                Ok(PluginCloseStep::AwaitingInput { .. } | PluginCloseStep::Blocked { .. }) | Err(_) => semio_framework_job::InteractiveJobCloseStep::Blocked,
                Ok(PluginCloseStep::Complete) => semio_framework_job::InteractiveJobCloseStep::Complete,
            }
        }

        fn terminal_is_empty(&self) -> bool {
            ArtifactReservedToolJob::terminal_is_empty(self)
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum FrameworkReservedStage {
        Admitted,
        Cursor,
        Retiring,
    }

    macro_rules! framework_reserved_job {
        ($job:ident, $factory:ident, $route:literal, $route_index:literal, $raw:literal, $items:literal, $work:literal, $output:literal) => {
            pub struct $job {
                raw: Vec<u8>,
                envelope_cursor: usize,
                item_cursor: usize,
                total_items: usize,
                stage: FrameworkReservedStage,
                contract: semio_framework::ToolExecutionContract,
                operation: Option<semio_framework_job::Operation>,
                closing: bool,
            }

            impl $job {
                pub(crate) fn new(raw: Vec<u8>, total_items: usize) -> Self {
                    Self {
                        raw,
                        envelope_cursor: 0,
                        item_cursor: 0,
                        total_items,
                        stage: FrameworkReservedStage::Admitted,
                        contract: semio_framework::ToolExecutionContract::resumable($raw, $items, $work, $output, 7_500, 1, 1),
                        operation: None,
                        closing: false,
                    }
                }

                fn cursor_state(&self) -> Vec<u8> {
                    let mut state = vec![$route_index, self.stage as u8];
                    state.extend_from_slice(&(self.envelope_cursor as u64).to_le_bytes());
                    state.extend_from_slice(&(self.raw.len() as u64).to_le_bytes());
                    state.extend_from_slice(&(self.item_cursor as u64).to_le_bytes());
                    state.extend_from_slice(&(self.total_items as u64).to_le_bytes());
                    state
                }

                fn checkpoint(&self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::Checkpoint {
                    let state = self.cursor_state();
                    semio_framework_job::Checkpoint { state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CheckpointState, &state), applied_progress: self.envelope_cursor.saturating_add(self.item_cursor) as u64 }
                }
            }

            impl semio_framework_job::InteractiveJob for $job {
                fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
                    if cx.is_cancelled() {
                        return semio_framework_job::StepOutcome::Cancelled;
                    }
                    match self.stage {
                        FrameworkReservedStage::Admitted => {
                            self.stage = FrameworkReservedStage::Cursor;
                            cx.set_stage(concat!("framework-reserved-", $route, "-envelope"));
                            let state = self.cursor_state();
                            semio_framework_job::StepOutcome::PreviewReady(retained_job_payload(cx, semio_framework_job::JobPayloadStream::Preview, &state))
                        }
                        FrameworkReservedStage::Cursor => {
                            let envelope_remaining = self.raw.len().saturating_sub(self.envelope_cursor);
                            let item_remaining = self.total_items.saturating_sub(self.item_cursor);
                            let remaining = if envelope_remaining != 0 { envelope_remaining } else { item_remaining };
                            let units = remaining.min(4_096).min(cx.fuel_remaining() as usize).min(self.contract.max_work_units_per_step as usize);
                            if envelope_remaining != 0 {
                                self.envelope_cursor += units;
                            } else {
                                self.item_cursor += units;
                            }
                            cx.consume_fuel(units as u64);
                            if cx.is_cancelled() {
                                return semio_framework_job::StepOutcome::Cancelled;
                            }
                            if self.envelope_cursor < self.raw.len() || self.item_cursor < self.total_items {
                                semio_framework_job::StepOutcome::CheckpointReady(self.checkpoint(cx))
                            } else {
                                self.stage = FrameworkReservedStage::Retiring;
                                cx.set_stage(concat!("framework-reserved-", $route, "-commit-ready"));
                                semio_framework_job::StepOutcome::CheckpointReady(self.checkpoint(cx))
                            }
                        }
                        FrameworkReservedStage::Retiring => {
                            if self.raw.len() > self.contract.max_output_bytes {
                                return semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault {
                                    detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, concat!("framework reserved ", $route, " output exceeds its exact cap").as_bytes()),
                                });
                            }
                            semio_framework_job::StepOutcome::Complete(semio_framework_job::CommitCandidate {
                                state: semio_framework_job::RetainedJobPayload::empty(semio_framework_job::JobPayloadStream::CommitState),
                                output: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CommitOutput, &self.raw),
                            })
                        }
                    }
                }

                fn begin_close(&mut self) {
                    self.closing = true;
                }

                fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
                    self.closing = true;
                    if !self.raw.is_empty() {
                        if maximum_items == 0 || maximum_bytes == 0 {
                            return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
                        }
                        let released_bytes = self.raw.len().min(maximum_bytes);
                        self.raw.truncate(self.raw.len() - released_bytes);
                        return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 1, released_bytes };
                    }
                    self.operation = None;
                    semio_framework_job::InteractiveJobCloseStep::Complete
                }

                fn terminal_is_empty(&self) -> bool {
                    self.closing && self.raw.is_empty() && self.operation.is_none()
                }
            }

            impl ArtifactReservedJob for $job {
                fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
                    Ok(match semio_framework_job::InteractiveJob::close_step(self, maximum_items, maximum_bytes) {
                        semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                        semio_framework_job::InteractiveJobCloseStep::Blocked => PluginCloseStep::Blocked { reason: "framework reserved route close is blocked" },
                        semio_framework_job::InteractiveJobCloseStep::Complete => PluginCloseStep::Complete,
                    })
                }

                fn terminal_is_empty(&self) -> bool {
                    semio_framework_job::InteractiveJob::terminal_is_empty(self)
                }
            }

            pub struct $factory<A: ArtifactApp> {
                keys: Vec<semio_framework::ToolFactoryKey>,
                marker: std::marker::PhantomData<fn() -> A>,
            }

            impl<A: ArtifactApp> $factory<A> {
                fn new(controller_id: &str) -> Self {
                    Self { keys: vec![semio_framework::ToolFactoryKey::new(controller_id, $route)], marker: std::marker::PhantomData }
                }
            }

            impl<A: ArtifactApp> semio_framework::ToolJobFactory for $factory<A> {
                type Payload = ArtifactReservedToolJob;
                type Job = ArtifactReservedToolJob;

                fn keys(&self) -> &[semio_framework::ToolFactoryKey] {
                    &self.keys
                }

                fn payload_schema_id(&self) -> &str {
                    concat!("framework.reserved.", $route, ".v1")
                }

                fn classification(&self) -> semio_framework::InteractiveJobClassification {
                    semio_framework::InteractiveJobClassification::Migrated
                }

                fn execution_contract(&self) -> semio_framework::ToolExecutionContract {
                    semio_framework::ToolExecutionContract::resumable($raw, $items, $work, $output, 7_500, 1, 1)
                }

                fn create_job(&mut self, operation: semio_framework_job::Operation, mut payload: Self::Payload) -> Result<Self::Job, semio_framework::ToolJobFactoryError> {
                    payload.bind_operation(operation)?;
                    Ok(payload)
                }
            }

            impl<A: ArtifactApp> ArtifactOwnedToolJobFactory for $factory<A> {
                type Owner = A;
                const TOOL_IDS: &'static [&'static str] = &[$route];
                const DOCUMENT_SCHEMA: &'static str = A::DOCUMENT_SCHEMA;
                const PUBLICATION_CONTRACTS: &'static [ArtifactToolPublicationContract] = &[ArtifactToolPublicationContract { tool_id: $route, lanes: &[ArtifactToolPublicationLane::HostOnly] }];
            }
        };
    }

