    #[derive(Default)]
    pub struct PluginExchangeOutput {
        pub frames: Vec<Vec<u8>>,
        pub effects: Vec<Vec<u8>>,
        pub events: Vec<Vec<u8>>,
        pub retry_command: Option<(u64, PluginCommandIngress)>,
