//! 📝️ Direct publication-presence replacement payload and inverse behavior.

use super::super::{PublicationPresence, PublicationPresenceMutation};
use protocol::{MutationKind, MutationOutcome, OpBinary, OpText, ProtocolError, SemanticDescriptor};
use semio_framework_value_derive::{FromValue, ToValue};

#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize, ToValue, FromValue, dsl::MutationLeaf)]
#[mutation_leaf(contract = ::protocol)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
#[value(rename_all = "camelCase", deny_unknown_fields)]
pub struct ChangePublicationPresence {
    pub revision: u64,
}

impl ChangePublicationPresence {
    pub const TEXT_OPCODE: &'static str = "change-publication-presence";
    pub const BINARY_TAG: u8 = 0x51;

    fn parse_revision(line: &str) -> Result<u64, semio_framework_diagnostic::TextError> {
        let revision = line.strip_prefix(&format!("{} ", Self::TEXT_OPCODE)).ok_or_else(|| semio_framework_diagnostic::TextError::new(format!("unknown publication presence op '{line}'"), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
        if revision.is_empty() || !revision.bytes().all(|byte| byte.is_ascii_digit()) {
            return Err(semio_framework_diagnostic::TextError::new("publication presence revision must be one unsigned decimal", semio_framework_diagnostic::TextSpan::at(1, 1)));
        }
        revision.parse().map_err(|_| semio_framework_diagnostic::TextError::new("publication presence revision is outside u64", semio_framework_diagnostic::TextSpan::at(1, 1)))
    }
}

impl OpText for ChangePublicationPresence {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        Ok(Self { revision: Self::parse_revision(line)? })
    }

    fn print_op(&self) -> String {
        format!("{} {}", Self::TEXT_OPCODE, self.revision)
    }
}

impl OpBinary for ChangePublicationPresence {
    fn encode_op(&self) -> Result<Vec<u8>, ProtocolError> {
        let mut bytes = Vec::with_capacity(9);
        bytes.push(Self::BINARY_TAG);
        bytes.extend_from_slice(&self.revision.to_be_bytes());
        Ok(bytes)
    }

    fn decode_op(bytes: &[u8]) -> Result<Self, ProtocolError> {
        if bytes.len() != 9 || bytes.first() != Some(&Self::BINARY_TAG) {
            return Err(ProtocolError::Malformed { what: "change-publication-presence", offset: 0, detail: "expected tag 0x51 and eight revision bytes".into() });
        }
        Ok(Self { revision: u64::from_be_bytes(bytes[1..].try_into().expect("exact binary revision width")) })
    }
}

impl MutationKind<PublicationPresence, PublicationPresenceMutation> for ChangePublicationPresence {
    const SEMANTICS: SemanticDescriptor = SemanticDescriptor { verb: "change", entity: "publication-presence", kind: "change-publication-presence", record: "ChangedPublicationPresence" };

    fn diff(&self, _base: &PublicationPresence) -> MutationOutcome<super::super::PublicationPresenceDiff> {
        MutationOutcome::new(super::super::PublicationPresenceDiff { revision: Some(self.revision) })
    }

    fn inverse(&self, base: &PublicationPresence) -> Vec<PublicationPresenceMutation> {
        vec![Self { revision: base.revision }.into()]
    }

    fn label(&self) -> semio_framework_ui_locale::LocalizedLabel {
        semio_framework_ui_locale::LocalizedLabel::native(&format!("Change publication presence to {}", self.revision), &format!("Veröffentlichungspräsenz auf {} ändern", self.revision))
    }
}

