//! 📊️ `dsl_family_sheet` — the calc-sheet family notation kit, shared by fem2d/3d and the
//! 15 norm-family apps (`en1990`-`en1999`, `din4108`, `din16798`, `din18599`, `iso16757`,
//! `vdi3805`). `crate::os_dsl::schema::Shape::Expr`/`ExprValue` deliberately "parses/prints the formula, never
//! evaluates it" (its own doc comment says so, naming this exact role: "resolved by the consuming
//! technology"). This crate is that consuming technology's evaluator, plus the self-verifying
//! `name = expr -> value` trace line the architecture plan calls for: `canonicalize_trace`
//! recomputes the expression against a variable environment and rewrites the stored value, so a
//! calc sheet's printed trace can never silently drift from what its own formula actually computes.
//!
//! Depends on `dsl_schema` (for `ExprValue`/`parse_expr_text`/`print_expr`) in addition to
//! `dsl_core` — unlike `dsl_notation`, which deliberately stays `dsl_core`-only because its edge
//! grammar is a `Shape::Wire` successor still pending migration, `Shape::Expr` has no such pending
//! migration to avoid colliding with: reusing it directly is exactly right.

use crate::os_dsl::schema::{parse_expr_text, print_expr, ExprOp, ExprValue};
use semio_framework_dsl::lex;
use semio_framework_diagnostic::Limits;
use semio_framework_diagnostic::TextError;
use semio_framework_diagnostic::TextSpan;
use semio_framework_dsl::TokenKind;
use std::collections::HashMap;

//#region 🔖️Evaluate
/// 🚫️ Why an expression failed to evaluate — never a panic, always a diagnosable value.
#[derive(Clone, Debug, PartialEq)]
pub enum EvalError {
    UnknownVariable(String),
    UnknownFunction(String, usize),
    DivisionByZero,
}

impl std::fmt::Display for EvalError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            EvalError::UnknownVariable(name) => write!(f, "unknown variable `{name}`"),
            EvalError::UnknownFunction(name, arity) => write!(f, "unknown function `{name}` with {arity} argument(s)"),
            EvalError::DivisionByZero => write!(f, "division by zero"),
        }
    }
}

/// 🧮️ Evaluates an `ExprValue` against a variable environment. Supports the small,
/// deliberately-closed function set a calc sheet actually needs (`min`, `max`, `abs`, `sqrt`) —
/// not a general call-out mechanism; an unrecognized name/arity is a diagnosed `EvalError`, never
/// a silent 0 or a panic.
// 🚫️async: E1 pure recursive evaluator, consumed by `Iterator::map` sync closure in the `Call` arm
// below — and confirmed sync-by-design by every existing call site, including test assertions that
// compare its `Result` directly with no `.await` in sight — see R9
pub fn evaluate(expr: &ExprValue, env: &HashMap<String, f64>) -> Result<f64, EvalError> {
    match expr {
        ExprValue::Num(v) => Ok(*v),
        ExprValue::Var(name) => env.get(name).copied().ok_or_else(|| EvalError::UnknownVariable(name.clone())),
        ExprValue::Neg(inner) => Ok(-evaluate(inner, env)?),
        ExprValue::Binary(op, l, r) => {
            let (lv, rv) = (evaluate(l, env)?, evaluate(r, env)?);
            match op {
                ExprOp::Add => Ok(lv + rv),
                ExprOp::Sub => Ok(lv - rv),
                ExprOp::Mul => Ok(lv * rv),
                ExprOp::Div => {
                    if rv == 0.0 {
                        Err(EvalError::DivisionByZero)
                    } else {
                        Ok(lv / rv)
                    }
                }
            }
        }
        ExprValue::Call(name, args) => {
            let values = args.iter().map(|a| evaluate(a, env)).collect::<Result<Vec<_>, _>>()?;
            match (name.as_str(), values.as_slice()) {
                ("min", [a, b]) => Ok(a.min(*b)),
                ("max", [a, b]) => Ok(a.max(*b)),
                ("abs", [a]) => Ok(a.abs()),
                ("sqrt", [a]) => Ok(a.sqrt()),
                _ => Err(EvalError::UnknownFunction(name.clone(), values.len())),
            }
        }
    }
}
//#endregion 🔖️Evaluate

//#region 🔖️Trace
/// 📈️ One self-verifying calc-sheet line: `name = expr -> value`. `value` is whatever was
/// last printed — `canonicalize_trace` is what re-derives it from `expr`/`env` and keeps it honest;
/// parsing alone doesn't check it (a stale/hand-edited trace parses fine as data — it's
/// `canonicalize_trace`'s job to catch drift, exactly like every other canonicalizer in this
/// engine catches non-canonical-but-parseable input).
#[derive(Clone, Debug, PartialEq)]
pub struct Trace {
    pub name: String,
    pub expr: ExprValue,
    pub value: f64,
}

async fn find_arrow_after(tokens: &[semio_framework_dsl::SpannedToken], after: usize) -> Option<usize> {
    tokens.iter().position(|t| t.kind == TokenKind::Arrow).filter(|&i| i > after)
}

/// 🔌️ Parses one standalone trace line: `name = expr -> value`.
pub async fn parse_trace_text(text: &str) -> Result<Trace, TextError> {
    let limits = Limits::default();
    let tokens: Vec<_> = lex(text, &limits, false)?.into_iter().filter(|t| !t.kind.is_trivia() && t.kind != TokenKind::Eof).collect();

    let name_token = tokens.first().filter(|t| t.kind == TokenKind::Ident).ok_or_else(|| TextError::new("expected a trace name", TextSpan::at(1, 1)))?;
    let name = name_token.text.as_str().to_string();
    let equals_index = 1;
    if tokens.get(equals_index).map(|t| t.kind) != Some(TokenKind::Equals) {
        return Err(TextError::new("expected `=` after the trace name", tokens.get(equals_index).map_or(TextSpan::at(1, 1), |t| t.span)));
    }

    let arrow_index = find_arrow_after(&tokens, equals_index).await.ok_or_else(|| TextError::new("expected `->` closing the trace's expression", TextSpan::at(1, 1)))?;
    let expr_start = tokens[equals_index].byte_range.1 as usize;
    let expr_end = tokens[arrow_index].byte_range.0 as usize;
    let expr = parse_expr_text(text[expr_start..expr_end].trim())?;

    let value_token = tokens.get(arrow_index + 1).filter(|t| matches!(t.kind, TokenKind::Float | TokenKind::Int)).ok_or_else(|| TextError::new("expected a number after `->`", tokens.get(arrow_index + 1).map_or(TextSpan::at(1, 1), |t| t.span)))?;
    let value: f64 = value_token.text.as_str().parse().map_err(|_| TextError::new(format!("not a valid number: {}", value_token.text.as_str()), value_token.span))?;

    if tokens.len() > arrow_index + 2 {
        return Err(TextError::new("unexpected trailing content after trace value", tokens[arrow_index + 2].span));
    }
    Ok(Trace { name, expr, value })
}

/// 🖨️ Canonical printer — prints `value` exactly as stored (does NOT recompute; that's
/// `canonicalize_trace`'s job, matching this engine's `parse`/`print`/`canonicalize` split).
pub async fn print_trace(trace: &Trace) -> String {
    format!("{} = {} -> {}", trace.name, print_expr(&trace.expr), semio_framework_dsl::format_f64(trace.value))
}

/// ♻️ The self-verifying step: parses `text`, RE-EVALUATES its expression against `env`
/// (ignoring whatever value was written), and reprints with the freshly computed value. A hand-
/// edited or stale trace canonicalizes to the correct one; an unparseable expression or an
/// evaluation error (unknown variable, etc.) surfaces as `Err`, never silently keeps the old value.
pub async fn canonicalize_trace(text: &str, env: &HashMap<String, f64>) -> Result<String, TextError> {
    let trace = parse_trace_text(text).await?;
    let value = evaluate(&trace.expr, env).map_err(|e| TextError::new(e.to_string(), TextSpan::at(1, 1)))?;
    Ok(print_trace(&Trace { value, ..trace }).await)
}
//#endregion 🔖️Trace

//#region 🔖️Tests
#[cfg(test)]
#[path = "🧪️tests/🔬️unit/🦀️.rs"]
mod tests;
//#endregion 🔖️Tests

//! 🖋️ `dsl_notation` — the shared notation toolkit handcrafted per-app grammars build on,
//! so "every grammar is handcrafted" doesn't mean "every grammar reinvents its own sub-parsers".
//! First resident: the edge/arrow literal, extended with an optional `[id:kind]` label so
//! graph-like documents can read as arrows (`a -> b`, `a -[e1:Connection]-> b`) instead of
//! flat `edges [id kind source target] {...}` tables. See `//#region 🔖️Edge` below.
//!
//! This crate deliberately depends on `dsl_core` only (its lexer/token alphabet), not
//! `dsl_schema`. It is additive and standalone: nothing in the repo calls it yet. The existing
//! `Shape::Wire`/`WireValue` in `dsl_schema` (the only current graph-arrow grammar, consumed by
//! `flow`, `procedural2d/3d`, `sequence`, `mathematical`, `dag`, `pack_value`, and
//! `math::graph::dsl`) is intentionally left untouched here: several of those consumer
//! trees have live uncommitted work in progress as of this writing, so migrating `Shape::Wire`
//! onto this toolkit is deferred to when that work has landed (see the ticket's collision-map.txt
//! and the `handcrafted-grammar-for-every-artifact` plan, wave W4e). This crate proves the
//! labeled-edge notation in isolation, ready to be adopted then.

use semio_framework_dsl::lex;
use semio_framework_diagnostic::Limits;
use semio_framework_dsl::SpannedToken;
use semio_framework_diagnostic::TextError;
use semio_framework_diagnostic::TextSpan;
use semio_framework_dsl::TokenKind;

//#region 🔖️Edge

/// 🕸️ One endpoint of an edge statement: `id[:kind][@port]`.
#[derive(Clone, Debug, PartialEq, Default)]
pub struct EdgeNode {
    pub id: String,
    pub kind: Option<String>,
    pub port: Option<String>,
}

/// 🔗️ The optional id/kind label carried by a bracketed edge arrow — `[e1:Connection]`,
/// `[e1]`, `[:Connection]`. Reuses Jack's existing `-[r:Kind]->` relationship-pattern bracket
/// notation (`🧮️math/🕸️graph/🗣️dsl`) rather than inventing a second bracket-free spelling, so the
/// two labeled-arrow grammars already in the repo agree with each other.
#[derive(Clone, Debug, PartialEq, Default)]
pub struct EdgeLabel {
    pub id: Option<String>,
    pub kind: Option<String>,
}

impl EdgeLabel {
    pub fn is_empty(&self) -> bool {
        self.id.is_none() && self.kind.is_none()
    }
}

/// 🔀️ The arrow between `from` and a linked node: direction plus an optional label.
#[derive(Clone, Debug, PartialEq)]
pub struct EdgeLink {
    pub directed: bool,
    pub label: EdgeLabel,
    pub to: EdgeNode,
}

/// 🕸️ One edge statement (or a bare node declaration if `link` is `None`).
///
/// Surface forms — `<-` and its labeled/reversed counterpart are sugar only, normalized by
/// endpoint-swap so the stored value (and everything reprinted from it) only ever holds a
/// forward-directed or undirected link, exactly like today's `crate::os_dsl::schema::WireValue`:
///
/// | written                     | normalized to (from, link)                              |
/// |------------------------------|----------------------------------------------------------|
/// | `a -> b`                     | `(a, directed=true,  label=∅,        to=b)`               |
/// | `a -- b`                     | `(a, directed=false, label=∅,        to=b)`               |
/// | `a <- b`                     | `(b, directed=true,  label=∅,        to=a)` (swapped)     |
/// | `a -[e1:Connection]-> b`     | `(a, directed=true,  label=e1:Connection, to=b)`          |
/// | `a -[e1]- b`                 | `(a, directed=false, label=e1,       to=b)`               |
/// | `a -[:Connection]-> b`       | `(a, directed=true,  label=:Connection, to=b)`            |
/// | `a <-[e1:Connection]- b`     | `(b, directed=true,  label=e1:Connection, to=a)` (swapped) |
///
/// Endpoints are `id[:kind][@port]` (unchanged from `WireValue::WireNode`).
#[derive(Clone, Debug, PartialEq)]
pub struct EdgeValue {
    pub from: EdgeNode,
    pub link: Option<EdgeLink>,
}

struct Cursor {
    tokens: Vec<SpannedToken>,
    pos: usize,
}

impl Cursor {
    fn new(tokens: Vec<SpannedToken>) -> Self {
        let tokens = tokens.into_iter().filter(|t| !t.kind.is_trivia()).collect();
        Self { tokens, pos: 0 }
    }

    fn peek(&self) -> &SpannedToken {
        &self.tokens[self.pos.min(self.tokens.len() - 1)]
    }

    fn peek_at(&self, offset: usize) -> Option<&SpannedToken> {
        self.tokens.get(self.pos + offset)
    }

    fn advance(&mut self) -> SpannedToken {
        let token = self.tokens[self.pos.min(self.tokens.len() - 1)].clone();
        if self.pos < self.tokens.len() - 1 {
            self.pos += 1;
        }
        token
    }

    fn expect(&mut self, kind: TokenKind) -> Result<SpannedToken, TextError> {
        if self.peek().kind == kind {
            Ok(self.advance())
        } else {
            Err(TextError::new(format!("expected {kind:?}, found {:?}", self.peek().kind), self.peek().span))
        }
    }

    fn span(&self) -> TextSpan {
        self.peek().span
    }
}

fn parse_edge_node(cursor: &mut Cursor) -> Result<EdgeNode, TextError> {
    let id = cursor.expect(TokenKind::Ident)?.text.as_str().to_string();
    let kind = if cursor.peek().kind == TokenKind::Colon {
        cursor.advance();
        Some(cursor.expect(TokenKind::Ident)?.text.as_str().to_string())
    } else {
        None
    };
    let port = if cursor.peek().kind == TokenKind::At {
        cursor.advance();
        Some(cursor.expect(TokenKind::Ident)?.text.as_str().to_string())
    } else {
        None
    };
    Ok(EdgeNode { id, kind, port })
}

pub fn decode_fused_edge_arrow(text: &str) -> Result<(bool, EdgeLabel), TextError> {
    let body = text.strip_prefix('-').ok_or_else(|| TextError::new("fused edge must start with `-`", TextSpan::at(1, 1)))?;
    let (core, directed) = if let Some(core) = body.strip_suffix('>') {
        (core, true)
    } else if let Some(core) = body.strip_suffix('-') {
        (core, false)
    } else {
        return Err(TextError::new("fused edge must end with `>` or `-`", TextSpan::at(1, 1)));
    };
    if core.is_empty() {
        return Err(TextError::new("fused edge label is empty", TextSpan::at(1, 1)));
    }
    let (id, kind) = if let Some(rest) = core.strip_prefix(':') {
        (None, Some(rest.to_string()))
    } else if let Some((id_part, kind_part)) = core.split_once(':') {
        (Some(id_part.to_string()), Some(kind_part.to_string()))
    } else {
        (Some(core.to_string()), None)
    };
    Ok((directed, EdgeLabel { id, kind }))
}

fn print_fused_edge_arrow(label: &EdgeLabel, directed: bool) -> String {
    let mut out = String::from('-');
    if let Some(id) = &label.id {
        out.push_str(id);
    }
    if let Some(kind) = &label.kind {
        out.push(':');
        out.push_str(kind);
    }
    out.push(if directed { '>' } else { '-' });
    out
}

fn parse_edge_label(cursor: &mut Cursor) -> Result<EdgeLabel, TextError> {
    cursor.expect(TokenKind::LBracket)?;
    let id = if cursor.peek().kind == TokenKind::Ident { Some(cursor.advance().text.as_str().to_string()) } else { None };
    let kind = if cursor.peek().kind == TokenKind::Colon {
        cursor.advance();
        Some(cursor.expect(TokenKind::Ident)?.text.as_str().to_string())
    } else {
        None
    };
    let label = EdgeLabel { id, kind };
    if label.is_empty() {
        return Err(TextError::new("edge label `[...]` must name an id and/or a `:kind`", cursor.span()));
    }
    cursor.expect(TokenKind::RBracket)?;
    Ok(label)
}

/// 🕸️ Parses one edge (or bare node) statement from an already-lexed cursor.
fn parse_edge(cursor: &mut Cursor) -> Result<EdgeValue, TextError> {
    let mut from = parse_edge_node(cursor)?;
    let link = match cursor.peek().kind {
        TokenKind::Arrow => {
            cursor.advance();
            let to = parse_edge_node(cursor)?;
            Some(EdgeLink { directed: true, label: EdgeLabel::default(), to })
        }
        TokenKind::DashArrow => {
            cursor.advance();
            let to = parse_edge_node(cursor)?;
            Some(EdgeLink { directed: false, label: EdgeLabel::default(), to })
        }
        TokenKind::BackArrow => {
            cursor.advance();
            let label = if cursor.peek().kind == TokenKind::LBracket {
                let label = parse_edge_label(cursor)?;
                cursor.expect(TokenKind::Minus)?;
                label
            } else {
                EdgeLabel::default()
            };
            let to = parse_edge_node(cursor)?;
            let swapped_to = std::mem::replace(&mut from, to);
            Some(EdgeLink { directed: true, label, to: swapped_to })
        }
        TokenKind::Minus if cursor.peek_at(1).map(|t| t.kind) == Some(TokenKind::LBracket) => {
            cursor.advance();
            let label = parse_edge_label(cursor)?;
            let directed = match cursor.peek().kind {
                TokenKind::Arrow => {
                    cursor.advance();
                    true
                }
                TokenKind::Minus => {
                    cursor.advance();
                    false
                }
                other => return Err(TextError::new(format!("expected `->` or `-` to close a labeled edge, found {other:?}"), cursor.span())),
            };
            let to = parse_edge_node(cursor)?;
            Some(EdgeLink { directed, label, to })
        }
        TokenKind::EdgeArrow => {
            let token = cursor.advance();
            let (directed, label) = decode_fused_edge_arrow(&token.text.as_str())?;
            let to = parse_edge_node(cursor)?;
            Some(EdgeLink { directed, label, to })
        }
        _ => None,
    };
    Ok(EdgeValue { from, link })
}

/// 🔌️ Lexes + parses one standalone edge literal — the entry point family/app grammars
/// call for the `edge` macro-production.
pub fn parse_edge_text(text: &str) -> Result<EdgeValue, TextError> {
    let limits = Limits::default();
    let tokens = lex(text, &limits, false)?;
    let mut cursor = Cursor::new(tokens);
    let edge = parse_edge(&mut cursor)?;
    if cursor.peek().kind != TokenKind::Eof {
        return Err(TextError::new(format!("unexpected trailing {:?} after edge literal", cursor.peek().kind), cursor.span()));
    }
    Ok(edge)
}

fn print_edge_node(node: &EdgeNode, out: &mut String) {
    out.push_str(&node.id);
    if let Some(kind) = &node.kind {
        out.push(':');
        out.push_str(kind);
    }
    if let Some(port) = &node.port {
        out.push('@');
        out.push_str(port);
    }
}

/// 🖨️ Canonical printer for [`EdgeValue`] — `parse_edge_text(print_edge(x)) == x` is the
/// round-trip law every macro-production in this toolkit must satisfy.
///
/// Labeled arrows print with a leading space before the opening `-[`: `a` is `is_ident_continue`
/// through the whole run of `-`, and the shared `dsl_core` lexer only stops an identifier early at
/// a `-` when the *next* char is `>` or `-` (so plain `->`/`--` tokenize cleanly) — it has no
/// special case for a following `[`. Without the space, `a-[e1:Connection]->b` would lex as ident
/// `"a-"` followed by `[`, not `a` then a fresh `-`. A leading space sidesteps this by ending the
/// identifier at whitespace instead, with no change to the shared lexer needed. The unlabeled
/// forms (`->`/`--`) are unaffected by this and keep the original no-space style unchanged.
pub fn print_edge(edge: &EdgeValue) -> String {
    let mut out = String::new();
    print_edge_node(&edge.from, &mut out);
    if let Some(link) = &edge.link {
        if link.label.is_empty() {
            out.push_str(if link.directed { "->" } else { "--" });
        } else {
            out.push(' ');
            out.push_str(&print_fused_edge_arrow(&link.label, link.directed));
        }
        print_edge_node(&link.to, &mut out);
    }
    out
}
//#endregion 🔖️Edge

//#region 🔖️Quantity
/// 📐️ Parses a number glued to a unit suffix — `210GPa`, `0.8kN/m2`, `45%` — converting
/// into `native`'s scale. `dsl_core`'s number lexer doesn't glue the suffix on itself (`210GPa`
/// lexes as two adjacent tokens, `Float("210")` then `Ident("GPa")`, exactly like
/// `crate::os_dsl::schema::parse_scalar`'s existing `Quantity`/`Angle` shapes already rely on) — this checks
/// the two tokens are byte-adjacent (no whitespace) before treating the ident as a unit suffix
/// rather than the start of the next statement. A number with no suffix at all is accepted too,
/// read as already being in `native`'s unit. Rejects a suffix whose dimension doesn't match
/// `native`'s (a length unit on an angle field, say) rather than silently reinterpreting it.
pub fn parse_quantity_text(text: &str, native: &'static semio_framework_dsl::UnitSpec) -> Result<f64, TextError> {
    let limits = Limits::default();
    let tokens: Vec<_> = lex(text, &limits, false)?.into_iter().filter(|t| !t.kind.is_trivia() && t.kind != TokenKind::Eof).collect();
    let number = tokens.first().ok_or_else(|| TextError::new("expected a quantity", TextSpan::at(1, 1)))?;
    if !matches!(number.kind, TokenKind::Float | TokenKind::Int) {
        return Err(TextError::new(format!("expected a number, found {:?}", number.kind), number.span));
    }
    let raw: f64 = number.text.as_str().parse().map_err(|_| TextError::new(format!("not a valid number: {}", number.text.as_str()), number.span))?;

    let suffix = tokens.get(1).filter(|t| t.kind == TokenKind::Ident && t.byte_range.0 == number.byte_range.1);
    let value = match suffix {
        Some(suffix_token) => {
            let symbol = suffix_token.text.as_str();
            let unit = semio_framework_dsl::unit_by_symbol(&symbol).ok_or_else(|| TextError::new(format!("unknown unit `{symbol}`"), suffix_token.span))?;
            semio_framework_dsl::convert(raw, unit, native).ok_or_else(|| TextError::new(format!("unit `{symbol}` is not compatible with `{}`", native.symbol), suffix_token.span))?
        }
        None => raw,
    };

    let consumed = if suffix.is_some() { 2 } else { 1 };
    if tokens.len() > consumed {
        return Err(TextError::new("unexpected trailing content after quantity", tokens[consumed].span));
    }
    Ok(value)
}

/// 🖨️ Canonical printer — always suffixes in `native`'s own unit (never the alien unit a
/// value might have been parsed from), so re-parsing the printed form is always a same-unit,
/// lossless round trip.
pub fn print_quantity(value: f64, native: &'static semio_framework_dsl::UnitSpec) -> String {
    format!("{}{}", semio_framework_dsl::format_f64(value), native.symbol)
}

/// 📐️ `parse_quantity_text` specialized to degrees: a bare number with no suffix is read
/// as degrees (unlike `parse_quantity_text`'s general "no suffix = already-native-unit" rule,
/// this pins the no-suffix case specifically, since degrees are what the architecture calls the
/// canonical angle unit); `rad`/`turn` suffixes convert in.
pub fn parse_angle_text(text: &str) -> Result<f64, TextError> {
    let deg = semio_framework_dsl::unit_by_symbol("deg").expect("`deg` is a built-in unit");
    parse_quantity_text(text, deg)
}

/// 🖨️ Canonical printer for an angle in degrees — `45°` (the `°` symbol, not `deg`).
pub fn print_angle(value_deg: f64) -> String {
    let degree_symbol = semio_framework_dsl::unit_by_symbol("°").expect("`°` is a built-in unit");
    format!("{}{}", semio_framework_dsl::format_f64(value_deg), degree_symbol.symbol)
}
