    let ops = vec![DerivedMutation::SetCategory { category: "roof".to_string() }, DerivedMutation::SetAirtightness { n50: 0.9 }, DerivedMutation::Reset];
    for op in ops {
        crate::os_store::test_support::assert_op_text_binary_equivalence(&op);
