//! 🛬️ Controlled native schema parsing uses borrowed lookahead and caller-admitted owned fields.

use semio_framework_dsl::language;
use semio_framework_diagnostic::TextError;
use semio_framework_diagnostic::TextSpan;
use semio_framework_diagnostic::Limits;
use semio_framework_dsl::TokenKind;
use semio_framework_dsl::parse_f64;
use super::*;
use crate::os_dsl::NativeDecodeControl;
use std::mem::size_of;

#[derive(Clone,Copy)]
struct Token<'a>{kind:TokenKind,text:&'a str,start:usize,end:usize,span:TextSpan}

struct Reader<'s,'c,'p>{source:&'s str,position:usize,line:u32,column:u32,lookahead:[Option<Token<'s>>;2],limits:Limits,tokens:usize,nodes:usize,control:&'c mut NativeDecodeControl<'p>}

impl<'s,'c,'p> Reader<'s,'c,'p>{
    fn metadata(&mut self,producer:&RecordSpecProducer)->Result<RecordSpec,TextError>{producer.decode(self.control).map_err(|error|self.error(error.into_message()))}
    fn error(&self,message:impl Into<String>)->TextError{TextError::new(message,TextSpan::at(self.line,self.column))}
    fn charge(&mut self,bytes:usize)->Result<(),TextError>{self.control.charge(bytes).map_err(|error|self.error(error.into_message()))}
    fn copy(&mut self,text:&str)->Result<String,TextError>{self.control.copy_text(text).map_err(|error|self.error(error.into_message()))}
    fn character(&self)->Option<char>{self.source[self.position..].chars().next()}
    fn consume(&mut self)->Result<char,TextError>{let c=self.character().ok_or_else(||self.error("unexpected native text end"))?;self.position+=c.len_utf8();if c=='\n'{self.line=self.line.checked_add(1).ok_or_else(||self.error("native line count overflow"))?;self.column=1;}else{self.column=self.column.checked_add(1).ok_or_else(||self.error("native column count overflow"))?;}self.control.advance(c.len_utf8()).map_err(|error|self.error(error.into_message()))?;Ok(c)}
    fn scan(&mut self)->Result<Token<'s>,TextError>{
        loop{while self.character().is_some_and(char::is_whitespace){self.consume()?;}if self.character()!=Some('#'){break;}while self.character().is_some_and(|c|c!='\n'){self.consume()?;}}
        let start=self.position;let span=TextSpan::at(self.line,self.column);let mut content_start=start;let mut content_end;
        let Some(c)=self.character()else{return Ok(Token{kind:TokenKind::Eof,text:"",start,end:start,span});};
