    fn wire_label(&mut self)->Result<WireEdgeLabel,TextError>{self.expect(TokenKind::LBracket)?;let id=if self.kind()?==TokenKind::Ident{let token=self.take()?;Some(self.copy(token.text)?)}else{None};let kind=if self.kind()?==TokenKind::Colon{self.take()?;let token=self.expect(TokenKind::Ident)?;Some(self.copy(token.text)?)}else{None};if id.is_none()&&kind.is_none(){return Err(self.error("native wire label requires an identity or kind"));}self.expect(TokenKind::RBracket)?;Ok(WireEdgeLabel{id,kind})}
    fn wire(&mut self,depth:usize)->Result<WireValue,TextError>{
        let mut from=self.wire_node()?;let mut edge_label=WireEdgeLabel::default();let token=self.peek(0)?;
        let edge=match token.kind{
            TokenKind::Arrow|TokenKind::DashArrow=>{self.take()?;Some((token.kind==TokenKind::Arrow,self.wire_node()?))},
            TokenKind::BackArrow=>{self.take()?;if self.kind()?==TokenKind::LBracket{edge_label=self.wire_label()?;self.expect(TokenKind::Minus)?;}let to=self.wire_node()?;Some((true,std::mem::replace(&mut from,to)))},
            TokenKind::Minus if self.peek(1)?.kind==TokenKind::LBracket=>{self.take()?;edge_label=self.wire_label()?;let arrow=self.take()?;if !matches!(arrow.kind,TokenKind::Arrow|TokenKind::DashArrow){return Err(self.error("native wire label requires an arrow"));}Some((arrow.kind==TokenKind::Arrow,self.wire_node()?))},
            TokenKind::EdgeArrow=>{self.take()?;let body=&token.text[1..token.text.len()-1];let(id,kind)=if let Some(kind)=body.strip_prefix(':'){(None,Some(kind))}else if let Some((id,kind))=body.split_once(':'){(Some(id),Some(kind))}else{(Some(body),None)};edge_label=WireEdgeLabel{id:id.map(|value|self.copy(value)).transpose()?,kind:kind.map(|value|self.copy(value)).transpose()?};Some((token.text.ends_with('>'),self.wire_node()?))},
            _=>None
        };
        let properties=if self.kind()?==TokenKind::LBrace{self.dynamic(depth+1)?}else{DslValue::Object(Vec::new())};Ok(WireValue{from,edge,edge_label,properties})
    }
    fn fixed_numbers(&mut self,count:usize)->Result<FieldValue,TextError>{let mut values=Vec::new();for index in 0..count{if index!=0{self.expect(TokenKind::Comma)?;}let(value,_)=self.number()?;self.push(&mut values,FieldValue::Float(value))?;}if self.kind()?==TokenKind::Comma{return Err(self.error("native coordinate arity mismatch"));}Ok(FieldValue::Tuple(values))}
    fn table(&mut self,make:RecordSpecProducer,depth:usize)->Result<FieldValue,TextError>{
        let spec=self.metadata(&make)?;validate_table_columns(&spec)?;self.expect(TokenKind::LBracket)?;let mut columns=Vec::new();while self.kind()?!=TokenKind::RBracket{let token=self.expect(TokenKind::Ident)?;let field=spec.fields.iter().find(|field|field.key==token.text).ok_or_else(||self.error("unknown native table column"))?;if columns.iter().any(|column:&&FieldSpec|column.id==field.id){return Err(self.error("duplicate native table column"));}if self.kind()?==TokenKind::Colon{self.take()?;self.expect(TokenKind::Ident)?;}self.push(&mut columns,field)?;}self.take()?;self.expect(TokenKind::LBrace)?;let mut rows=Vec::new();while self.kind()?!=TokenKind::RBrace{if columns.is_empty(){return Err(self.error("native table requires columns"));}self.node(depth)?;let mut record=RecordValue::default();for field in &columns{let value=if self.kind()?==TokenKind::Placeholder{self.take()?;FieldValue::Absent}else if let Shape::Record(make)=field.shape{self.expect(TokenKind::LBrace)?;let record={let spec=self.metadata(&make)?;self.record(&spec,depth+1)?};self.expect(TokenKind::RBrace)?;FieldValue::Record(record)}else{self.shape(&field.shape,depth+1)?};self.insert(&mut record,field.id,value)?;}for field in &spec.fields{if !record.fields.contains_key(&field.id){self.insert(&mut record,field.id,FieldValue::Absent)?;}}self.push(&mut rows,FieldValue::Record(record))?;}self.take()?;Ok(FieldValue::List(rows))
    }
    fn dynamic(&mut self,depth:usize)->Result<DslValue,TextError>{
        self.node(depth)?;let token=self.peek(0)?;match token.kind{
            TokenKind::LBrace=>{self.take()?;let mut entries=Vec::new();while let Some(key)=self.dynamic_key()?{let key=self.text(key)?;self.take()?;self.expect(TokenKind::Equals)?;let value=self.dynamic(depth+1)?;self.push(&mut entries,(key,value))?;}self.expect(TokenKind::RBrace)?;Ok(DslValue::Object(entries))},
            TokenKind::LBracket=>{self.take()?;let mut values=Vec::new();while self.kind()?!=TokenKind::RBracket{let value=self.dynamic(depth+1)?;self.push(&mut values,value)?;}self.take()?;Ok(DslValue::Array(values))},
            TokenKind::Text=>{self.take()?;self.text(token).map(DslValue::String)},
            TokenKind::Int=>{self.take()?;if token.text.len()>2048{return Err(self.error("native dynamic integer is too long"));}let value=if let Ok(value)=token.text.parse::<u64>(){Number::UInt(value)}else if let Ok(value)=token.text.parse::<i64>(){Number::Int(value)}else{Number::Float(parse_f64(token.text).map_err(|_|self.error("invalid native dynamic number"))?)};Ok(DslValue::Number(value))},
            TokenKind::Float=>self.number().map(|(value,_)|DslValue::Number(Number::Float(value))),
            TokenKind::Ident=>{self.take()?;match token.text{"null"=>Ok(DslValue::Null),"true"=>Ok(DslValue::Bool(true)),"false"=>Ok(DslValue::Bool(false)),"nan"|"inf"=>parse_f64(token.text).map(|value|DslValue::Number(Number::Float(value))).map_err(|_|self.error("invalid native dynamic number")),"bytes64"=>{self.expect(TokenKind::LParen)?;let token=self.expect(TokenKind::Text)?;let bytes=self.octets(token)?;self.expect(TokenKind::RParen)?;Ok(DslValue::Bytes(bytes))},_=>Err(self.error("unknown native dynamic literal"))}},
            _=>Err(self.error("invalid native dynamic value"))
        }
    }
    fn expression(&mut self,minimum:u8,depth:usize)->Result<ExprValue,TextError>{
        self.node(depth)?;let token=self.peek(0)?;let left=match token.kind{
            TokenKind::Minus=>{self.take()?;self.charge(size_of::<ExprValue>())?;ExprValue::Neg(Box::new(self.expression(3,depth+1)?))},
            TokenKind::LParen=>{self.take()?;let value=self.expression(0,depth+1)?;self.expect(TokenKind::RParen)?;value},
            TokenKind::Ident|TokenKind::Text if token.kind==TokenKind::Text||!matches!(token.text,"inf"|"nan")=>{self.take()?;let name=if token.kind==TokenKind::Text{self.text(token)?}else{self.copy(token.text)?};if self.kind()?==TokenKind::LParen{self.take()?;let mut values=Vec::new();if self.kind()?!=TokenKind::RParen{loop{let value=self.expression(0,depth+1)?;self.push(&mut values,value)?;if self.kind()?!=TokenKind::Comma{break;}self.take()?;}}self.expect(TokenKind::RParen)?;ExprValue::Call(name,values)}else{ExprValue::Var(name)}},
            _=>ExprValue::Num(self.number()?.0)
        };
        self.expression_tail(left,minimum,depth)
    }
    fn expression_tail(&mut self,mut left:ExprValue,minimum:u8,depth:usize)->Result<ExprValue,TextError>{
        let mut count=0usize;
        loop{let token=self.peek(0)?;let glued=matches!(token.kind,TokenKind::Int|TokenKind::Float)&&token.text.starts_with('-');let operator=if glued{Some(ExprOp::Sub)}else{match token.kind{TokenKind::Plus=>Some(ExprOp::Add),TokenKind::Minus=>Some(ExprOp::Sub),TokenKind::Star=>Some(ExprOp::Mul),TokenKind::Slash=>Some(ExprOp::Div),_=>None}};let Some(operator)=operator else{break;};let precedence=operator.precedence();if precedence<minimum{break;}count+=1;self.node(depth+count)?;self.charge(size_of::<ExprValue>()*2)?;let right=if glued{let value=ExprValue::Num(-self.number()?.0);self.expression_tail(value,precedence+1,depth+1)?}else{self.take()?;self.expression(precedence+1,depth+1)?};left=ExprValue::Binary(operator,Box::new(left),Box::new(right));}Ok(left)
    }
}

/// 🧭️ Parses exact schema-owned Text with bounded borrowed scanning, cumulative ownership and interior cancellation.
pub fn parse_exact_controlled(text:&str,spec:&RecordSpec,options:&ParseOptions,control:&mut NativeDecodeControl<'_>)->Result<Cst,TextError>{
    options.limits.check_bytes(text.len())?;
    control.scoped_stage(|control|{control.begin_stage(text.len()).map_err(|error|TextError::new(error.into_message(),TextSpan::at(1,1)))?;let mut reader=Reader{source:text,position:0,line:1,column:1,lookahead:[None,None],limits:options.limits,tokens:0,nodes:0,control};let record=reader.record(spec,0)?;reader.expect(TokenKind::Eof)?;Ok(record)})
}

/// 🧮️ Parses a bare semantic expression under the same owned native allocation and input work control.
pub fn parse_expr_text_controlled(text:&str,limits:&Limits,control:&mut NativeDecodeControl<'_>)->Result<ExprValue,TextError>{limits.check_bytes(text.len())?;control.scoped_stage(|control|{control.begin_stage(text.len()).map_err(|error|TextError::new(error.into_message(),TextSpan::at(1,1)))?;let mut reader=Reader{source:text,position:0,line:1,column:1,lookahead:[None,None],limits:*limits,tokens:0,nodes:0,control};let value=reader.expression(0,0)?;reader.expect(TokenKind::Eof)?;Ok(value)})}

//! 🫧️ The FEM editors' local-only transient: the gumball gesture each window has in flight, persisted between the
//! dispatches of one streamed gesture — its tool statechart configuration by stable ids, the admission and base
//! revision it opened on, and its open `ToolTransaction`'s provisional entries in value form. Artifact-level rather
//! than window-level so the SIBLING windows paint the gesture's preview too (the results window re-solves the moved
//! structure while the drag goes on), and keyed by the owning window id so two windows never clobber each other's
//! gesture. Never history, never shared; fem 2d and fem 3d both keep their gestures here.
//! Schema of record: `🧬️schema/🔣️.json`; design `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️09/☀️30/NON-DESTRUCTIVE-HISTORY-EDITING/📋️design.md` §5.

use semio_framework_tool_machine::{ToolRefusal, ToolTransaction, ToolTransactionState};
use semio_framework_value_derive::{FromValue, ToValue};
use std::collections::BTreeMap;

//#region 🔖️State
/// 🫧️ Every open gumball gesture of one FEM artifact instance, by owning window id.
#[derive(Clone, Debug, Default, PartialEq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct FemGumballTransient {
    pub gestures: BTreeMap<String, FemGumballGesture>,
}

/// 💾️ One window's in-flight gumball gesture.
#[derive(Clone, Debug, PartialEq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct FemGumballGesture {
    pub states: Vec<String>,
    pub verb: String,
    pub authoring_seed: String,
    pub base_revision: String,
    pub transaction: protocol::TransactionRef,
    pub entries: Vec<FemGumballEntry>,
}

/// 🧷️ One provisional entry of the open transaction, its mutation in value form.
#[derive(Clone, Debug, PartialEq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct FemGumballEntry {
    pub key: String,
    pub mutation: dsl::DslValue,
}

impl FemGumballGesture {
    /// 💾️ The gesture a runner's parts persist: `Some` only while its transaction is open.
    pub fn persist<M: dsl::ToValue>(states: Vec<String>, verb: &str, authoring_seed: &str, base_revision: &str, transaction: Option<ToolTransaction<M>>) -> Option<Self> {
        let transaction = transaction.filter(|transaction| transaction.state() == ToolTransactionState::Open)?;
        Some(Self {
            states,
            verb: verb.to_string(),
            authoring_seed: authoring_seed.to_string(),
            base_revision: base_revision.to_string(),
            transaction: transaction.reference().clone(),
            entries: transaction.entries().iter().map(|(key, mutation)| FemGumballEntry { key: key.clone(), mutation: dsl::ToValue::to_value(mutation) }).collect(),
        })
    }

    /// 🧷️ The provisional entries decoded back into mutations; one that no longer decodes refuses the gesture (`Closed`).
    pub fn entries<M: dsl::FromValue>(&self) -> Result<Vec<(String, M)>, ToolRefusal> {
        self.entries.iter().map(|entry| Ok((entry.key.clone(), dsl::FromValue::from_value(entry.mutation.clone()).map_err(|_| ToolRefusal::Closed)?))).collect()
    }

    /// ⏯️ The statechart snapshot this gesture persisted, restored for machine `T` with `context`; a configuration the
    /// current chart cannot restore is refused (`Closed`), so the caller drops the gesture with zero trace.
    pub fn snapshot<T: machine::Machine>(&self, context: T::Context) -> Result<machine::Snapshot<T>, ToolRefusal> {
        let persisted = machine::PersistedSnapshot { version: 1, fingerprint: T::definition().fingerprint, states: self.states.clone(), history: Vec::new(), done: false };
        machine::restore::<T, machine::NoMigrations>(&persisted, context, &[]).map_err(|_| ToolRefusal::Closed)
    }
}

impl FemGumballTransient {
    /// 🪟️ This transient with `window`'s gesture replaced by `gesture` (`None` clears it).
    pub fn with_gesture(&self, window: &str, gesture: Option<FemGumballGesture>) -> Self {
        let mut gestures = self.gestures.clone();
        match gesture {
            Some(gesture) => gestures.insert(window.to_string(), gesture),
            None => gestures.remove(window),
        };
        Self { gestures }
    }

    /// 👁️ `document` with every open gesture's provisional entries applied — the preview every window of this
    /// instance paints, never history. An entry that does not decode or apply is skipped.
    pub fn preview<S: Clone, M: dsl::FromValue + protocol::Mutation<S>>(&self, document: &S) -> Option<S> {
        let entries: Vec<M> = self.gestures.values().flat_map(|gesture| &gesture.entries).filter_map(|entry| dsl::FromValue::from_value(entry.mutation.clone()).ok()).collect();
        (!entries.is_empty()).then(|| entries.iter().fold(document.clone(), |state, mutation| protocol::MutationDiff::apply(protocol::Mutation::diff(mutation, &state).diff(), &state).unwrap_or(state)))
    }
}
//#endregion 🔖️State

//#region 🛠️Drive
/// 🎚️ Where one transform dispatch sits in a gumball gesture: a one-shot `Once`, a `Stream` tick into the window's
/// open transaction, the `Commit` that ends it, or a host `Abort` with its reason.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FemGumballPhase {
    Once,
    Stream,
    Commit,
    Abort(semio_framework_tool_machine::ToolAbortReason),
}

impl FemGumballPhase {
    /// 🧩️ Reads a transform verb's `phase` (`stream` | `commit` | `abort`, absent = one-shot) and an abort's `reason`
    /// (`blur`, `captureLost`, `baseMoved`, `frozen`, `retired`; absent = `tool`); `None` for an unknown one.
    pub fn parse(phase: Option<&str>, reason: Option<&str>) -> Option<Self> {
        match phase {
            None => Some(Self::Once),
            Some("stream") => Some(Self::Stream),
            Some("commit") => Some(Self::Commit),
            Some("abort") => reason.map_or(Some(semio_framework_tool_machine::ToolAbortReason::Tool), semio_framework_tool_machine::ToolAbortReason::parse).map(Self::Abort),
            Some(_) => None,
        }
    }
}

/// 🛠️ One FEM editor's gumball tool for one dispatch: a tool-machine runner over that editor's relative leaf, started
/// at rest or resumed from the gesture its window persisted.
pub trait FemGumballTool: Sized {
    type Leaf;
    type Mutation;
    fn start(verb: &str, authoring_seed: &str, base_revision: &str) -> Result<Self, ToolRefusal>;
    fn resume(gesture: &FemGumballGesture) -> Result<Self, ToolRefusal>;
    fn verb(&self) -> &str;
    fn base_revision(&self) -> &str;
    fn at_rest(&self) -> bool;
    fn abort(&mut self, reason: semio_framework_tool_machine::ToolAbortReason);
    fn send(&mut self, phase: FemGumballPhase, tick: Option<Self::Leaf>) -> Result<semio_framework_tool_machine::ToolStep<Self::Mutation>, ToolRefusal>;
    fn persist(self) -> Option<FemGumballGesture>;
}

/// 🧮️ What one gumball dispatch did: the transaction it committed (publish it as ONE edit) and the window's next
/// transient when the dispatch opened, advanced, committed or dropped a gesture.
pub struct FemGumballDrive<M> {
    pub committed: Option<(protocol::TransactionRef, Vec<M>)>,
    pub transient: Option<FemGumballTransient>,
}

/// 🛠️ Drives `window`'s gumball tool through ONE dispatch of a transform verb. `Once` commits `tick` as one transaction;
/// `Stream` upserts it into the window's open transaction (opening it on the first tick), `Commit` folds it in and
/// commits the whole gesture, `Abort` drops the open gesture with zero trace. An open gesture another verb or a one-shot
/// interrupts is aborted `captureLost`; one whose base moved under it is aborted `baseMoved`, and a stream tick or
/// commit that found it is dropped with it.
pub fn fem_gumball_drive<T: FemGumballTool>(transient: &FemGumballTransient, window: &str, verb: &str, phase: FemGumballPhase, tick: Option<T::Leaf>, authoring_seed: &str, base_revision: &str) -> FemGumballDrive<T::Mutation> {
    use semio_framework_tool_machine::{ToolAbortReason, ToolStep};
    let persisted = transient.gestures.get(window);
    let open = persisted.and_then(|gesture| T::resume(gesture).ok());
    let dropped = FemGumballDrive { committed: None, transient: persisted.map(|_| transient.with_gesture(window, None)) };
    let open = match (open, phase) {
        (Some(mut tool), FemGumballPhase::Abort(reason)) => {
            tool.abort(reason);
            return dropped;
        }
        (None, FemGumballPhase::Abort(_)) => return dropped,
        (Some(mut tool), _) if tool.base_revision() != base_revision => {
            tool.abort(ToolAbortReason::BaseMoved);
            if phase != FemGumballPhase::Once {
                return dropped;
            }
            None
        }
        (Some(mut tool), _) if tool.verb() != verb || phase == FemGumballPhase::Once => {
            tool.abort(ToolAbortReason::CaptureLost);
            None
        }
        (open, _) => open,
    };
    let Some(mut tool) = open.or_else(|| T::start(verb, authoring_seed, base_revision).ok()) else { return dropped };
    let step = tool.send(phase, tick);
    let next = transient.with_gesture(window, tool.persist());
    let changed = (next != *transient).then_some(next);
    match step {
        Ok(ToolStep::Committed(reference, mutations)) => FemGumballDrive { committed: Some((reference, mutations)), transient: changed },
        Ok(_) | Err(_) => FemGumballDrive { committed: None, transient: changed },
    }
}
//#endregion 🛠️Drive

//#region 🔖️Mutation
