//! lowpoly -> gltf
//!
//! Real glTF 2.0 GLB export through `io::encode_glb`: every object with non-empty `mesh_content`
//! becomes one node/mesh pair (world-space positions, fan-triangulated n-gons).
//!
//! 🔖 `IoFidelity::Lossy`: objects and names survive, n-gons come back as triangles, paint does not.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_gltf::io::{encode_glb, GltfAccessorType, GltfComponentType};
use semio_s_artifact_stdio_gltf::schema::snapshot::{
    GltfAccessor, GltfAsset, GltfBuffer, GltfBufferView, GltfDocument, GltfMesh, GltfNode, GltfPrimitive, GltfScene, GltfSourceForm,
    GltfSnapshot,
};
use semio_s_artifact_stdio_gltf::STDIO_GLTF_DOCUMENT_SCHEMA;

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<GltfSnapshot, semio_framework_diagnostic::TextError> {
    let parts = world_parts("gltf", snapshot)?;
    let mut bin = Vec::new();
    let mut accessors = Vec::new();
    let mut buffer_views = Vec::new();
    let mut meshes = Vec::new();
    let mut nodes = Vec::new();
    for part in &parts {
        if part.positions.is_empty() || part.faces.is_empty() {
            continue;
        }
        let pos_offset = bin.len();
        let mut min = [f32::INFINITY; 3];
        let mut max = [f32::NEG_INFINITY; 3];
        for p in &part.positions {
            let v = [p[0] as f32, p[1] as f32, p[2] as f32];
            for i in 0..3 {
                min[i] = min[i].min(v[i]);
                max[i] = max[i].max(v[i]);
                bin.extend_from_slice(&v[i].to_le_bytes());
            }
        }
        let pos_len = bin.len() - pos_offset;
        let pos_view = buffer_views.len();
        buffer_views.push(GltfBufferView {
            buffer: 0,
            byte_offset: pos_offset,
            byte_length: pos_len,
            byte_stride: None,
            target: Some(34962),
            name: None,
            extensions: None,
            extras: None,
        });
        let pos_accessor = accessors.len();
        accessors.push(GltfAccessor {
            buffer_view: Some(pos_view),
            byte_offset: 0,
            component_type: GltfComponentType::Float,
            normalized: false,
            count: part.positions.len(),
            kind: GltfAccessorType::Vec3,
            max: Some(max.iter().map(|v| f64::from(*v)).collect()),
            min: Some(min.iter().map(|v| f64::from(*v)).collect()),
            sparse: None,
            name: None,
            extensions: None,
            extras: None,
        });

        let mut indices: Vec<u32> = Vec::new();
        for face in &part.faces {
            if face.len() < 3 {
                continue;
            }
            for i in 1..face.len() - 1 {
                indices.extend_from_slice(&[face[0], face[i], face[i + 1]]);
            }
        }
        if indices.is_empty() {
            continue;
        }
        while bin.len() % 4 != 0 {
            bin.push(0);
        }
        let idx_offset = bin.len();
        for index in &indices {
            bin.extend_from_slice(&index.to_le_bytes());
        }
        let idx_len = bin.len() - idx_offset;
        let idx_view = buffer_views.len();
        buffer_views.push(GltfBufferView {
            buffer: 0,
            byte_offset: idx_offset,
            byte_length: idx_len,
            byte_stride: None,
            target: Some(34963),
            name: None,
            extensions: None,
            extras: None,
        });
        let idx_accessor = accessors.len();
        accessors.push(GltfAccessor {
            buffer_view: Some(idx_view),
            byte_offset: 0,
            component_type: GltfComponentType::UnsignedInt,
            normalized: false,
            count: indices.len(),
            kind: GltfAccessorType::Scalar,
            max: None,
            min: None,
            sparse: None,
            name: None,
            extensions: None,
            extras: None,
        });

        let mesh_index = meshes.len();
        meshes.push(GltfMesh {
            primitives: vec![GltfPrimitive {
                attributes: vec![("POSITION".into(), pos_accessor)],
                indices: Some(idx_accessor),
                material: None,
                mode: Some(4),
                targets: Vec::new(),
                extensions: None,
                extras: None,
            }],
            weights: Vec::new(),
            name: Some(part.name.clone()),
            extensions: None,
            extras: None,
        });
        nodes.push(GltfNode {
            children: Vec::new(),
            mesh: Some(mesh_index),
            camera: None,
            skin: None,
            matrix: None,
            translation: None,
            rotation: None,
            scale: None,
            weights: Vec::new(),
            name: Some(part.name.clone()),
            extensions: None,
            extras: None,
        });
    }

    let node_indices: Vec<usize> = (0..nodes.len()).collect();
    let document = GltfDocument {
        asset: GltfAsset {
            version: "2.0".into(),
            generator: Some("semio.lowpoly".into()),
            copyright: None,
            min_version: None,
            extensions: None,
            extras: None,
        },
        scene: Some(0),
        scenes: vec![GltfScene { nodes: node_indices, name: None, extensions: None, extras: None }],
        nodes,
        meshes,
        accessors,
        buffer_views,
        buffers: vec![GltfBuffer { byte_length: bin.len(), uri: None, name: None, extensions: None, extras: None }],
        materials: Vec::new(),
        textures: Vec::new(),
        images: Vec::new(),
        samplers: Vec::new(),
        skins: Vec::new(),
        animations: Vec::new(),
        cameras: Vec::new(),
        extensions_used: Vec::new(),
        extensions_required: Vec::new(),
        extensions: None,
        extras: None,
    };
    Ok(GltfSnapshot { schema: STDIO_GLTF_DOCUMENT_SCHEMA.into(), document, buffers: vec![bin], source_form: GltfSourceForm::Glb })
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    encode_glb(&serialize(snapshot)?).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
}

//! lowpoly -> las
//!
//! Real LAS 1.x export through `io::encode_las`: every world-space mesh vertex becomes one point
//! record.
//!
//! 🔖 `IoFidelity::Lossy`: a point cloud of the vertices — faces, objects and paint do not survive,
//! so there is no las import.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_las::io::encode_las;
use semio_s_artifact_stdio_las::schema::snapshot::{LasHeader, LasPoint};
use semio_s_artifact_stdio_las::LasSnapshot;

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<LasSnapshot, semio_framework_diagnostic::TextError> {
    let mut points = Vec::new();
    let mut min = [f64::INFINITY; 3];
    let mut max = [f64::NEG_INFINITY; 3];
    for part in world_parts("las", snapshot)? {
        for p in &part.positions {
            for i in 0..3 {
                min[i] = min[i].min(p[i]);
                max[i] = max[i].max(p[i]);
            }
            points.push(LasPoint {
                x: p[0],
                y: p[1],
                z: p[2],
                intensity: 0,
                return_number: 1,
                number_of_returns: 1,
                scan_direction_flag: false,
                edge_of_flight_line: false,
                classification: 0,
                scan_angle_rank: 0,
                user_data: 0,
                point_source_id: 0,
                gps_time: None,
                rgb: None,
            });
        }
    }
    if min[0].is_infinite() {
        min = [0.0; 3];
        max = [0.0; 3];
    }
    let mut header = LasHeader::default();
    header.system_identifier = "semio.lowpoly".into();
    header.generating_software = "semio.lowpoly".into();
    header.min_x = min[0];
    header.min_y = min[1];
    header.min_z = min[2];
    header.max_x = max[0];
    header.max_y = max[1];
    header.max_z = max[2];
    header.number_of_point_records = points.len() as u32;
    Ok(LasSnapshot {
        header,
        points,
        ..Default::default()
    })
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    encode_las(&serialize(snapshot)?).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
}

//! lowpoly -> ply
//!
//! Real ASCII PLY export through `engine::encode_ply`: a `vertex` element (`float x/y/z`, world
//! space — scale → Euler-degree rotation → translation) and a `face` element
//! (`list uchar int vertex_indices`, widened to a `uint` count past 255 corners) holding every
//! object's original n-gons, concatenated. Objects with empty `mesh_content` contribute nothing.
//!
//! 🔖 `IoFidelity::Lossy`: geometry survives with n-gons kept; object boundaries, names and paint
//! do not.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_ply::engine::encode_ply;
use semio_s_artifact_stdio_ply::schema::snapshot::{PlyElement, PlyProperty, PlyRow, PlyScalarType, PlyValue};
use semio_s_artifact_stdio_ply::PlySnapshot;

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<PlySnapshot, semio_framework_diagnostic::TextError> {
    let mut vertex_rows = Vec::new();
    let mut face_rows = Vec::new();
    let mut max_corners = 0usize;
    for part in world_parts("ply", snapshot)? {
        let offset = vertex_rows.len() as u32;
        vertex_rows.extend(part.positions.iter().map(|p| PlyRow { values: vec![PlyValue::Float(p[0] as f32), PlyValue::Float(p[1] as f32), PlyValue::Float(p[2] as f32)] }));
        for face in &part.faces {
            max_corners = max_corners.max(face.len());
            face_rows.push(PlyRow { values: vec![PlyValue::List(face.iter().map(|&v| PlyValue::Int((v + offset) as i32)).collect())] });
        }
    }
    let mut ply = PlySnapshot::default();
    if !vertex_rows.is_empty() {
        let count_kind = if max_corners > 255 { PlyScalarType::UInt } else { PlyScalarType::UChar };
        ply.elements.push(PlyElement {
            name: "vertex".into(),
            count: u64::try_from(vertex_rows.len()).map_err(|_| crate::io::mesh_geometry::text_error("PLY vertex occurrence count exceeds u64"))?,
            properties: ["x", "y", "z"].iter().map(|n| PlyProperty::Scalar { name: (*n).into(), kind: PlyScalarType::Float }).collect(),
            rows: vertex_rows,
        });
        ply.elements.push(PlyElement { name: "face".into(), count: u64::try_from(face_rows.len()).map_err(|_| crate::io::mesh_geometry::text_error("PLY face occurrence count exceeds u64"))?, properties: vec![PlyProperty::List { name: "vertex_indices".into(), count_kind, value_kind: PlyScalarType::Int }], rows: face_rows });
    }
    Ok(ply)
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    encode_ply(&serialize(snapshot)?).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
}

//! lowpoly -> dwg
//!
//! Real DWG export: mesh vertices/faces (world space, fan-triangulated) go through
//! `mesh_to_dwg_drawing` -> `DwgSnapshot::from_drawing` -> `encode_dwg` (AC1024).
//!
//! 🔖 `IoFidelity::Lossy`: one polyface mesh of triangles — objects, names and paint do not survive.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_framework_plugin::MeshData;
use semio_s_artifact_stdio_dwg::{dwg_to_bytes, mesh_to_dwg_drawing, DwgSnapshot};

pub fn register() {}

pub fn serialize(snapshot: &LowpolySnapshot) -> Result<DwgSnapshot, semio_framework_diagnostic::TextError> {
    let mut mesh = MeshData::default();
    for part in world_parts("dwg", snapshot)? {
        let base = (mesh.positions.len() / 3) as u32;
        for p in &part.positions {
            mesh.positions.extend_from_slice(&[p[0] as f32, p[1] as f32, p[2] as f32]);
        }
        for face in &part.faces {
            if face.len() < 3 {
                continue;
            }
            for i in 1..face.len() - 1 {
                mesh.indices.extend_from_slice(&[base + face[0], base + face[i], base + face[i + 1]]);
            }
        }
    }
    let drawing = mesh_to_dwg_drawing(&mesh);
    DwgSnapshot::from_drawing(&drawing).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    let snap = serialize(snapshot)?;
    let drawing = snap.drawing.to_native().map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    dwg_to_bytes(&drawing).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
}

//! 💠️ lowpoly -> png — a shaded isometric picture of the model: every object's world-space n-gons
//! (`world_parts`, fan-triangulated) become one `s.stdio.semio/v1/mesh` painted by that subset's own
//! view leaf. Lowpoly is y-up and the view is z-up, so `(x, y, z)` is drawn as `(x, -z, y)`.
//!
//! 🔖 `IoFidelity::Lossy`: a picture, not the model — there is no png import.
use crate::io::mesh_geometry::world_parts;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_semio::standards::v1::subsets::base::schema::geometry::SemioPoint3;
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::io::{encode_mesh, SemioMeshFormat};
use semio_s_artifact_stdio_semio::standards::v1::subsets::mesh::schema::snapshot::{SemioMesh, SemioMeshSnapshot, SemioPrimitive, SemioTopology};

pub fn register() {}

pub fn serialize_bytes(snapshot: &LowpolySnapshot) -> Result<Vec<u8>, semio_framework_diagnostic::TextError> {
    let meshes = world_parts("png", snapshot)?
        .into_iter()
        .map(|part| SemioMesh {
            id: part.name.clone(),
            primitives: vec![SemioPrimitive {
                id: part.name,
                topology: SemioTopology::Triangles,
                positions: part.positions.iter().map(|p| SemioPoint3 { x: p[0], y: -p[2], z: p[1] }).collect(),
                normals: Vec::new(),
                uvs: Vec::new(),
                colors: Vec::new(),
                indices: part.faces.iter().filter(|face| face.len() >= 3).flat_map(|face| (1..face.len() - 1).flat_map(move |i| [face[0], face[i], face[i + 1]])).collect(),
                material_id: None,
            }],
        })
        .collect();
    encode_mesh(&SemioMeshSnapshot { meshes, ..SemioMeshSnapshot::default() }, SemioMeshFormat::Png).map_err(|error| semio_framework_diagnostic::TextError::new(format!("lowpoly->png: {error}"), semio_framework_diagnostic::TextSpan::at(1, 1)))
}

