//! lowpoly <- obj
//!
//! Geometry over the real `engine::decode_obj` grammar (never a second bespoke parser): any OBJ
//! (Blender, etc.) becomes real lowpoly objects — one per `o`
//!    object (falling back to `g` groups, then a single object), names from the file, vertex
//!    indices remapped per object, n-gons kept as n-gons. More than 64 parts merge into one
//!    object; a file without faces is rejected loudly.
use crate::io::mesh_geometry::{compact_part, snapshot_from_parts, text_error, PolygonPart};
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_obj::engine::decode_obj;
use semio_s_artifact_stdio_obj::ObjSnapshot;

pub fn register() {}

pub fn deserialize(from: &ObjSnapshot) -> Result<LowpolySnapshot, semio_framework_diagnostic::TextError> {
    snapshot_from_obj_geometry(from)
}

/// 🕸️ Real-geometry import (see module docs).
pub fn snapshot_from_obj_geometry(from: &ObjSnapshot) -> Result<LowpolySnapshot, semio_framework_diagnostic::TextError> {
    let positions: Vec<[f32; 3]> = from.vertices.iter().map(|v| [v.x as f32, v.y as f32, v.z as f32]).collect();
    let polygon = |face_index: usize| -> Vec<u32> { from.faces[face_index].vertices.iter().map(|fv| fv.vertex).collect() };

    // 🏷️ Face ownership: `o` objects first, else the first `g` group naming the face.
    let named: Vec<(String, &Vec<u64>)> = if !from.objects.is_empty() {
        from.objects.iter().map(|o| (o.name.clone(), &o.faces)).collect()
    } else {
        from.groups.iter().map(|g| (g.name.clone(), &g.faces)).collect()
    };
    let mut owner: Vec<Option<usize>> = vec![None; from.faces.len()];
    for (part_index, (_, faces)) in named.iter().enumerate() {
        for &face in faces.iter() {
            if let Some(slot) = usize::try_from(face).ok().and_then(|index| owner.get_mut(index)) {
                if slot.is_none() {
                    *slot = Some(part_index);
                }
            }
        }
    }
    let mut buckets: Vec<Vec<Vec<u32>>> = vec![Vec::new(); named.len()];
    let mut unowned: Vec<Vec<u32>> = Vec::new();
    for (face_index, slot) in owner.iter().enumerate() {
        match slot {
            Some(part_index) => buckets[*part_index].push(polygon(face_index)),
            None => unowned.push(polygon(face_index)),
        }
    }

    let mut parts: Vec<PolygonPart> = Vec::new();
    if !unowned.is_empty() {
        let name = if named.is_empty() { "Imported Mesh" } else { "Default" };
        parts.push(compact_part(name, &positions, &unowned).map_err(|e| text_error(format!("obj->lowpoly: {e}")))?);
    }
    for ((name, _), polygons) in named.iter().zip(buckets.iter()) {
        parts.push(compact_part(name, &positions, polygons).map_err(|e| text_error(format!("obj->lowpoly: {e}")))?);
    }
    snapshot_from_parts("obj", parts)
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<LowpolySnapshot, semio_framework_diagnostic::TextError> {
    let text = std::str::from_utf8(bytes).map_err(|e| semio_framework_diagnostic::TextError::new(e.to_string(), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    let snap = decode_obj(text).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    deserialize(&snap)
}

//! lowpoly <- ply
//!
//! Geometry over the real `engine::decode_ply` (ascii and both binary encodings): the `vertex` element's `x`/`y`/`z` columns plus the `face` element's
//!    `vertex_indices` (or `vertex_index`) list become ONE lowpoly object, n-gons kept. A file
//!    without faces is rejected loudly.
use crate::io::mesh_geometry::{compact_part, snapshot_from_parts, text_error};
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_ply::engine::decode_ply;
use semio_s_artifact_stdio_ply::schema::snapshot::{PlyElement, PlyValue};
use semio_s_artifact_stdio_ply::PlySnapshot;

pub fn register() {}

pub fn deserialize(from: &PlySnapshot) -> Result<LowpolySnapshot, semio_framework_diagnostic::TextError> {
    snapshot_from_ply_geometry(from)
}

fn scalar_f64(value: &PlyValue) -> Option<f64> {
    Some(match value {
        PlyValue::Char(v) => f64::from(*v),
        PlyValue::UChar(v) => f64::from(*v),
        PlyValue::Short(v) => f64::from(*v),
        PlyValue::UShort(v) => f64::from(*v),
        PlyValue::Int(v) => f64::from(*v),
        PlyValue::UInt(v) => f64::from(*v),
        PlyValue::Float(v) => f64::from(*v),
        PlyValue::Double(v) => *v,
        PlyValue::List(_) => return None,
    })
}

fn column(element: &PlyElement, names: &[&str]) -> Option<usize> {
    element.properties.iter().position(|p| names.contains(&p.name()))
}

/// 🕸️ Real-geometry import (see module docs).
pub fn snapshot_from_ply_geometry(from: &PlySnapshot) -> Result<LowpolySnapshot, semio_framework_diagnostic::TextError> {
    let vertex = from.elements.iter().find(|e| e.name == "vertex").ok_or_else(|| text_error("ply->lowpoly: no `vertex` element"))?;
    let face = from.elements.iter().find(|e| e.name == "face").ok_or_else(|| text_error("ply->lowpoly: no `face` element (point clouds are not meshes)"))?;
    let (Some(x), Some(y), Some(z)) = (column(vertex, &["x"]), column(vertex, &["y"]), column(vertex, &["z"])) else {
        return Err(text_error("ply->lowpoly: `vertex` element lacks x/y/z properties"));
    };
    let indices = column(face, &["vertex_indices", "vertex_index"]).ok_or_else(|| text_error("ply->lowpoly: `face` element lacks a vertex_indices/vertex_index list"))?;

    let mut positions = Vec::with_capacity(vertex.rows.len());
    for (row_index, row) in vertex.rows.iter().enumerate() {
        let read = |col: usize| row.values.get(col).and_then(scalar_f64).map(|v| v as f32).ok_or_else(|| text_error(format!("ply->lowpoly: vertex {row_index} has a non-scalar coordinate")));
        positions.push([read(x)?, read(y)?, read(z)?]);
    }
    let mut polygons = Vec::with_capacity(face.rows.len());
    for (row_index, row) in face.rows.iter().enumerate() {
        let Some(PlyValue::List(items)) = row.values.get(indices) else {
            return Err(text_error(format!("ply->lowpoly: face {row_index} vertex index list is missing")));
        };
        let mut polygon = Vec::with_capacity(items.len());
        for item in items {
            let value = scalar_f64(item).filter(|v| *v >= 0.0 && v.fract() == 0.0).ok_or_else(|| text_error(format!("ply->lowpoly: face {row_index} has an invalid vertex index")))?;
            polygon.push(value as u32);
        }
        polygons.push(polygon);
    }
    let part = compact_part("PLY Mesh", &positions, &polygons).map_err(|e| text_error(format!("ply->lowpoly: {e}")))?;
    snapshot_from_parts("ply", vec![part])
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<LowpolySnapshot, semio_framework_diagnostic::TextError> {
    let snap = decode_ply(bytes).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    deserialize(&snap)
}

//! lowpoly <- txt
//!
//! 📜️ Exact inverse of the export leaf: the txt body IS lowpoly's own `.lowpoly` DSL text
//! verbatim (CARRIER_TEXT law, see the export leaf's doc comment), so import is just
//! `store::ArtifactDsl::parse_dsl` on the body -- no second bespoke grammar to maintain.
use crate::schema::snapshot::text::parse_dsl;
use crate::schema::snapshot::LowpolySnapshot;
use semio_s_artifact_stdio_txt::TxtSnapshot;

pub fn register() {}

pub fn deserialize(from: &TxtSnapshot) -> Result<LowpolySnapshot, semio_framework_diagnostic::TextError> {
    parse_dsl(&from.to_body())
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<LowpolySnapshot, semio_framework_diagnostic::TextError> {
    let text = std::str::from_utf8(bytes).map_err(|e| semio_framework_diagnostic::TextError::new(e.to_string(), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
