// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn enc_snapshot(s: &SemioDocumentSnapshot) -> String {
    format!("[{},{},{}]", enc_list(&s.styles, enc_style), enc_list(&s.images, enc_image), enc_list(&s.blocks, enc_block))
}
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn dec_snapshot(s: &str) -> Result<SemioDocumentSnapshot, String> {
    let inner = strip_brackets(s)?;
    let parts = split_top_level(inner, ',');
    let [styles, images, blocks] = parts.as_slice() else { return Err(format!("snapshot: expected 3 fields, got {}", parts.len())) };
    Ok(SemioDocumentSnapshot {
        schema: crate::standards::v1::subsets::document::schema::snapshot::STDIO_SEMIODOCUMENT_DOCUMENT_SCHEMA.into(),
        styles: dec_list(styles, dec_style)?,
        images: dec_list(images, dec_image)?,
        blocks: dec_list(blocks, dec_block)?,
    })
}

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn print_document_mutation(m: &SemioDocumentMutation) -> String {
    match m {
        SemioDocumentMutation::SetSnapshot(set_snapshot::SetSnapshot { snapshot }) => format!("set-snapshot snapshot={}", enc_snapshot(snapshot)),
        SemioDocumentMutation::PatchSnapshot(patch_snapshot::PatchSnapshot { patch }) => semio_s_artifact_stdio_contract::editing::snapshot_patch_text(patch),
        SemioDocumentMutation::InsertBlock(insert_block::InsertBlock { path, block }) => format!("insert-block path={} block={}", enc_block_path(path), enc_block(block)),
        SemioDocumentMutation::RemoveBlock(remove_block::RemoveBlock { path }) => format!("remove-block path={}", enc_block_path(path)),
        SemioDocumentMutation::SetBlockContent(set_block_content::SetBlockContent { path, block }) => format!("set-block-content path={} block={}", enc_block_path(path), enc_block(block)),
        SemioDocumentMutation::SetParagraphStyle(set_paragraph_style::SetParagraphStyle { path, style_id }) => format!("set-paragraph-style path={} style-id={}", enc_block_path(path), encode_option(style_id, |v| enc_str(v))),
        SemioDocumentMutation::SetHeadingLevel(set_heading_level::SetHeadingLevel { path, level }) => format!("set-heading-level path={} level={}", enc_block_path(path), enc_u8(level)),
        SemioDocumentMutation::SetListOrdered(set_list_ordered::SetListOrdered { path, ordered }) => format!("set-list-ordered path={} ordered={}", enc_block_path(path), enc_bool(ordered)),
        SemioDocumentMutation::SetRunText(set_run_text::SetRunText { path, run_index, text }) => format!("set-run-text path={} run-index={} text={}", enc_block_path(path), run_index, enc_str(text)),
        SemioDocumentMutation::SetRunStyle(set_run_style::SetRunStyle { path, run_index, style }) => format!("set-run-style path={} run-index={} style={}", enc_block_path(path), run_index, enc_run_style_full(style)),
        SemioDocumentMutation::SetImageBlock(set_image_block::SetImageBlock { path, image_id, alt, width, height }) => {
            format!("set-image-block path={} image-id={} alt={} width={} height={}", enc_block_path(path), enc_str(image_id), enc_str(alt), encode_option(width, enc_f64), encode_option(height, enc_f64))
        }
        SemioDocumentMutation::InsertStyle(insert_style::InsertStyle { style }) => format!("insert-style style={}", enc_style(style)),
        SemioDocumentMutation::RemoveStyle(remove_style::RemoveStyle { id }) => format!("remove-style id={}", enc_str(id)),
        SemioDocumentMutation::SetStyleName(set_style_name::SetStyleName { id, name }) => format!("set-style-name id={} name={}", enc_str(id), enc_str(name)),
        SemioDocumentMutation::SetStyleBasedOn(set_style_based_on::SetStyleBasedOn { id, based_on }) => format!("set-style-based-on id={} based-on={}", enc_str(id), encode_option(based_on, |v| enc_str(v))),
        SemioDocumentMutation::InsertImage(insert_image::InsertImage { image }) => format!("insert-image image={}", enc_image(image)),
        SemioDocumentMutation::RemoveImage(remove_image::RemoveImage { id }) => format!("remove-image id={}", enc_str(id)),
        SemioDocumentMutation::SetImageBytes(set_image_bytes::SetImageBytes { id, mime, bytes }) => format!("set-image-bytes id={} mime={} bytes={}", enc_str(id), enc_str(mime), hex_encode(bytes)),
    }
}
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn parse_document_mutation(line: &str) -> Result<SemioDocumentMutation, String> {
    if let Some(source) = line.strip_prefix("patch-snapshot patch=") {
        let patch = semio_s_artifact_stdio_contract::editing::snapshot_patch_from_hex(source)?;
        return Ok(SemioDocumentMutation::PatchSnapshot(crate::standards::v1::subsets::document::schema::mutations::patch_snapshot::PatchSnapshot { patch }));
    }
    let (keyword, rest) = line.split_once(' ').unwrap_or((line, ""));
    let args: std::collections::BTreeMap<&str, &str> =
        rest.split(' ').filter(|s| !s.is_empty()).map(|tok| tok.split_once('=').ok_or_else(|| format!("document mutation: bad arg token {tok:?}"))).collect::<Result<Vec<_>, String>>()?.into_iter().collect();
    let arg = |k: &str| args.get(k).copied().ok_or_else(|| format!("document mutation: missing arg '{k}' for '{keyword}'"));
    let usize_arg = |k: &str| -> Result<usize, String> { arg(k)?.parse().map_err(|e: std::num::ParseIntError| e.to_string()) };
    match keyword {
        "set-snapshot" => Ok(SemioDocumentMutation::SetSnapshot(set_snapshot::SetSnapshot { snapshot: dec_snapshot(arg("snapshot")?)? })),
        "insert-block" => Ok(SemioDocumentMutation::InsertBlock(insert_block::InsertBlock { path: dec_block_path(arg("path")?)?, block: dec_block(arg("block")?)? })),
        "remove-block" => Ok(SemioDocumentMutation::RemoveBlock(remove_block::RemoveBlock { path: dec_block_path(arg("path")?)? })),
        "set-block-content" => Ok(SemioDocumentMutation::SetBlockContent(set_block_content::SetBlockContent { path: dec_block_path(arg("path")?)?, block: dec_block(arg("block")?)? })),
        "set-paragraph-style" => Ok(SemioDocumentMutation::SetParagraphStyle(set_paragraph_style::SetParagraphStyle { path: dec_block_path(arg("path")?)?, style_id: decode_option(arg("style-id")?, dec_str)? })),
        "set-heading-level" => Ok(SemioDocumentMutation::SetHeadingLevel(set_heading_level::SetHeadingLevel { path: dec_block_path(arg("path")?)?, level: dec_u8(arg("level")?)? })),
        "set-list-ordered" => Ok(SemioDocumentMutation::SetListOrdered(set_list_ordered::SetListOrdered { path: dec_block_path(arg("path")?)?, ordered: dec_bool(arg("ordered")?)? })),
        "set-run-text" => Ok(SemioDocumentMutation::SetRunText(set_run_text::SetRunText { path: dec_block_path(arg("path")?)?, run_index: usize_arg("run-index")?, text: dec_str(arg("text")?)? })),
        "set-run-style" => Ok(SemioDocumentMutation::SetRunStyle(set_run_style::SetRunStyle { path: dec_block_path(arg("path")?)?, run_index: usize_arg("run-index")?, style: dec_run_style_full(arg("style")?)? })),
        "set-image-block" => Ok(SemioDocumentMutation::SetImageBlock(set_image_block::SetImageBlock {
            path: dec_block_path(arg("path")?)?,
            image_id: dec_str(arg("image-id")?)?,
            alt: dec_str(arg("alt")?)?,
            width: decode_option(arg("width")?, dec_f64)?,
            height: decode_option(arg("height")?, dec_f64)?,
        })),
        "insert-style" => Ok(SemioDocumentMutation::InsertStyle(insert_style::InsertStyle { style: dec_style(arg("style")?)? })),
        "remove-style" => Ok(SemioDocumentMutation::RemoveStyle(remove_style::RemoveStyle { id: dec_str(arg("id")?)? })),
        "set-style-name" => Ok(SemioDocumentMutation::SetStyleName(set_style_name::SetStyleName { id: dec_str(arg("id")?)?, name: dec_str(arg("name")?)? })),
        "set-style-based-on" => Ok(SemioDocumentMutation::SetStyleBasedOn(set_style_based_on::SetStyleBasedOn { id: dec_str(arg("id")?)?, based_on: decode_option(arg("based-on")?, dec_str)? })),
        "insert-image" => Ok(SemioDocumentMutation::InsertImage(insert_image::InsertImage { image: dec_image(arg("image")?)? })),
        "remove-image" => Ok(SemioDocumentMutation::RemoveImage(remove_image::RemoveImage { id: dec_str(arg("id")?)? })),
        "set-image-bytes" => Ok(SemioDocumentMutation::SetImageBytes(set_image_bytes::SetImageBytes { id: dec_str(arg("id")?)?, mime: dec_str(arg("mime")?)?, bytes: hex_decode(arg("bytes")?)? })),
        other => Err(format!("document mutation: unknown keyword {other:?}")),
    }
}

impl OpText for SemioDocumentMutation {
    fn print_op(&self) -> String {
        print_document_mutation(self)
    }
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        parse_document_mutation(line).map_err(|e| semio_framework_diagnostic::TextError::new(e, semio_framework_diagnostic::TextSpan::at(1, 1)))
    }
}

//#region 🏷️WireTags
/// 🏷️ Op tags of `SemioDocumentMutation`, derived from the `record <kind> tag=<n>` lines of its `📡️.protocol.semio`.
const WIRE_PROTOCOL: &str = include_str!("💾️binary/📡️.protocol.semio");
const TAG_SET_SNAPSHOT: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-snapshot");
const TAG_PATCH_SNAPSHOT: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "patch-snapshot");
const TAG_INSERT_BLOCK: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "insert-block");
const TAG_REMOVE_BLOCK: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "remove-block");
const TAG_SET_BLOCK_CONTENT: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-block-content");
const TAG_SET_PARAGRAPH_STYLE: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-paragraph-style");
const TAG_SET_HEADING_LEVEL: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-heading-level");
const TAG_SET_LIST_ORDERED: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-list-ordered");
const TAG_SET_RUN_TEXT: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-run-text");
const TAG_SET_RUN_STYLE: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-run-style");
const TAG_SET_IMAGE_BLOCK: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-image-block");
const TAG_INSERT_STYLE: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "insert-style");
const TAG_REMOVE_STYLE: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "remove-style");
const TAG_SET_STYLE_NAME: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-style-name");
const TAG_SET_STYLE_BASED_ON: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-style-based-on");
const TAG_INSERT_IMAGE: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "insert-image");
const TAG_REMOVE_IMAGE: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "remove-image");
const TAG_SET_IMAGE_BYTES: u8 = dsl::protocol_record::tag_u8(WIRE_PROTOCOL, "set-image-bytes");
//#endregion 🏷️WireTags

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn wire_tag(m: &SemioDocumentMutation) -> u8 {
    match m {
        SemioDocumentMutation::SetSnapshot(..) => TAG_SET_SNAPSHOT,
        SemioDocumentMutation::PatchSnapshot(_) => TAG_PATCH_SNAPSHOT,
        SemioDocumentMutation::InsertBlock(..) => TAG_INSERT_BLOCK,
        SemioDocumentMutation::RemoveBlock(..) => TAG_REMOVE_BLOCK,
        SemioDocumentMutation::SetBlockContent(..) => TAG_SET_BLOCK_CONTENT,
        SemioDocumentMutation::SetParagraphStyle(..) => TAG_SET_PARAGRAPH_STYLE,
        SemioDocumentMutation::SetHeadingLevel(..) => TAG_SET_HEADING_LEVEL,
        SemioDocumentMutation::SetListOrdered(..) => TAG_SET_LIST_ORDERED,
        SemioDocumentMutation::SetRunText(..) => TAG_SET_RUN_TEXT,
        SemioDocumentMutation::SetRunStyle(..) => TAG_SET_RUN_STYLE,
        SemioDocumentMutation::SetImageBlock(..) => TAG_SET_IMAGE_BLOCK,
        SemioDocumentMutation::InsertStyle(..) => TAG_INSERT_STYLE,
        SemioDocumentMutation::RemoveStyle(..) => TAG_REMOVE_STYLE,
        SemioDocumentMutation::SetStyleName(..) => TAG_SET_STYLE_NAME,
        SemioDocumentMutation::SetStyleBasedOn(..) => TAG_SET_STYLE_BASED_ON,
        SemioDocumentMutation::InsertImage(..) => TAG_INSERT_IMAGE,
        SemioDocumentMutation::RemoveImage(..) => TAG_REMOVE_IMAGE,
        SemioDocumentMutation::SetImageBytes(..) => TAG_SET_IMAGE_BYTES,
    }
}
/// ✂️ Just the `key=value ...` argument tail of `print_document_mutation` (empty for
/// `no-mutation`) — the binary frame's `tag` byte already carries the keyword, so the text keyword
/// itself is redundant in the binary payload.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn print_document_mutation_args(m: &SemioDocumentMutation) -> String {
    match print_document_mutation(m).split_once(' ') {
        Some((_, rest)) => rest.to_string(),
        None => String::new(),
    }
}

/// ⚡️ ARTIFACT-SYSTEM-OVERHAUL-REAL-CODECS-RUNTIME-REUSE-EVOLUTION document wave: real binary op
/// frame, replacing the old `print_op().into_bytes()` text-as-binary shortcut. `format u8`
/// (`OP_BINARY_FORMAT` convention) + `tag u8` (the variant ordinal, see [`KINDS`]) are two
/// REAL fixed fields; the variant's own `key=value ...` argument payload follows as one opaque
/// trailing `bytes` chain — reusing the already-real, already-tested
/// `print_document_mutation`/`parse_document_mutation` text codec rather than re-deriving a second
/// independent encoding.
impl OpBinary for SemioDocumentMutation {
    fn encode_op(&self) -> Result<Vec<u8>, protocol::ProtocolError> {
        if let Self::PatchSnapshot(payload) = self {
            let mut out = vec![1, TAG_PATCH_SNAPSHOT];
            out.extend(protocol::OpBinary::encode_op(&payload.patch)?);
            return Ok(out);
        }
        const OP_BINARY_FORMAT: u8 = 1;
        let mut out = vec![OP_BINARY_FORMAT, wire_tag(self)];
        out.extend_from_slice(print_document_mutation_args(self).as_bytes());
        Ok(out)
    }
    fn decode_op(bytes: &[u8]) -> Result<Self, protocol::ProtocolError> {
        const OP_BINARY_FORMAT: u8 = 1;
        if bytes.len() < 2 {
            return Err(protocol::ProtocolError::Malformed { what: "op header", offset: 0, detail: "truncated (need format+tag)".to_string() });
        }
        if bytes[0] != OP_BINARY_FORMAT {
            return Err(protocol::ProtocolError::Malformed { what: "op format", offset: 0, detail: format!("unsupported op format {}", bytes[0]) });
        }
        if bytes[1] == TAG_PATCH_SNAPSHOT {
            return Ok(Self::PatchSnapshot(crate::standards::v1::subsets::document::schema::mutations::patch_snapshot::PatchSnapshot { patch: protocol::OpBinary::decode_op(&bytes[2..])? }));
        }
        let tag = bytes[1];
        let keyword = dsl::protocol_record::kind(WIRE_PROTOCOL, u64::from(tag)).ok_or_else(|| protocol::ProtocolError::Malformed { what: "op tag", offset: 1, detail: format!("tag {tag} names no record of 📡️.protocol.semio") })?;
        let args = std::str::from_utf8(&bytes[2..]).map_err(|e| protocol::ProtocolError::Malformed { what: "op utf8", offset: 2, detail: e.to_string() })?;
        let line = if args.is_empty() { keyword.to_string() } else { format!("{keyword} {args}") };
        Self::parse_op(&line).map_err(|e| protocol::ProtocolError::Malformed { what: "op text", offset: 2, detail: e.to_string() })
    }
}
