/// 📐️ Parsed `viewBox="min-x min-y width height"`.
#[derive(Clone, Copy, Debug, Default, PartialEq, value_derive::ToValue, value_derive::FromValue)]
#[value(rename_all = "camelCase")]
pub struct ViewBox {
