        XmlNode::Text { text } => Ok(SvgElement::TextNode(text.clone())),
        XmlNode::CData { text } => Ok(SvgElement::CData(text.clone())),
        XmlNode::Comment { text } => Ok(SvgElement::Comment(text.clone())),
