                let common = parse_common_attrs(attrs, &["x", "y", "width", "height", "rx", "ry"]);
                Ok(SvgElement::Rect {
                    common,
                    x: attr_f64(attrs, "x", 0.0)?,
                    y: attr_f64(attrs, "y", 0.0)?,
                    width: attr_f64(attrs, "width", 0.0)?,
                    height: attr_f64(attrs, "height", 0.0)?,
                    rx: attr_f64_opt(attrs, "rx")?,
