impl Default for SemioImageSnapshot {
    fn default() -> Self {
        Self { schema: STDIO_SEMIOIMAGE_DOCUMENT_SCHEMA.into(), width: 0, height: 0, colorspace: SemioColorspace::default(), bit_depth: 0, frames: Vec::new(), icc: None, metadata: Vec::new() }
    }
