    pub schema: String,
    #[state(artifact)]
    #[value(default)]
    pub header: IfcHeader,
    /// 🆔️ Id-keyed, order-preserving — the strong collection this artifact's diff/mutations work
    /// against (see `schema::diff::IfcEntitiesDiff`).
    #[state(artifact)]
    #[value(default)]
    pub entities: Vec<IfcEntity>,
