        let linetypes = match (a.linetypes, b.linetypes) {
            (None, None) => None,
            (Some(x), None) => Some(x),
            (None, Some(y)) => Some(y),
            (Some(x), Some(y)) => DxfLinetypesDiff::absorb(x, y),
        };
        let d = Self { layers, styles, linetypes };
