                    if !diff.removed.is_empty() || !diff.added.is_empty() {
                        paths.push(concat!("document/", $name).to_string());
                    } else {
                        paths.extend(diff.modified.iter().map(|entry| format!(concat!("document/", $name, "/{}"), entry.index)));
