#[artifact_schema(id = "s.stdio.semio.kit.diff")]
pub struct SemioKitDiff {
    #[state(artifact)]
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub types: Option<SemioKitTypeList>,
    #[state(artifact)]
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub designs: Option<SemioKitDesignList>,
    #[state(artifact)]
    #[value(default, skip_serializing_if = "Option::is_none")]
