        write_bin_rgb(w, &m.rgb);
    });
    write_bin_vec(&mut w, &d.added, |w, a: &PngPlteEntryAdded| {
        w.write_varint_u64(a.index as u64);
        write_bin_rgb(w, &a.rgb);
