#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue)]
#[value(tag = "colorType", rename_all = "camelCase")]
pub enum PngTransparency {
    Indexed { alpha: Vec<u8> },
    Grayscale { gray: u16 },
    Rgb { r: u16, g: u16, b: u16 },
}
//#endregion Transparency

//#region Ancillary
