pub fn register() {}

pub fn deserialize(from: &JsonSnapshot) -> Result<ShootingSnapshot, semio_framework_diagnostic::TextError> {
    let _ = SHOOTING_DOCUMENT_SCHEMA;
    let dsl_value: dsl::DslValue = from.to_serde_value().into();
