    "set-block-content",
    "set-run-text",
    "replace-xml-node",
    "set-run-formatting",
    "set-paragraph-style",
    "insert-table-row",
    "remove-table-row",
    "insert-xml-node",
    "remove-xml-node",
    "insert-style",
    "remove-style",
    "set-style-name",
