    semio_s_artifact_stdio_contract::editing::RENAME_SNAPSHOT_KEY_ACTION_ID,
    semio_s_artifact_stdio_contract::editing::REPLACE_SNAPSHOT_SOURCE_ACTION_ID,
];
const XML_ANY_RETAINED_PAYLOAD_SCHEMA: &str = "stdio.xml.tool-command.v1";
const XML_ANY_RETAINED_RAW_BYTES: usize = 16 * 1_024 * 1_024;
/// 🚦️ The example switch publishes into NO document lane: it hands the host one
/// `Effect::LoadDocument`, so its only lane is `HostOnly`. `set-node` publishes the artifact
/// mutation it reduces into, so its only lane is `Artifact`.
const XML_ANY_RETAINED_PUBLICATION_CONTRACTS: &[ArtifactToolPublicationContract] = &[
    ArtifactToolPublicationContract { tool_id: semio_s_artifact_stdio_contract::SET_ACTIVE_EXAMPLE_ACTION_ID, lanes: &[ArtifactToolPublicationLane::HostOnly] },
    ArtifactToolPublicationContract { tool_id: XML_ANY_KIT_ACTION_ID, lanes: &[ArtifactToolPublicationLane::Artifact] },
];

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn xml_any_retained_contract() -> ToolExecutionContract {
    ToolExecutionContract::bounded_first_step(XML_ANY_RETAINED_RAW_BYTES, 4_096, 1, XML_ANY_RETAINED_RAW_BYTES, 7_500)
}

/// 📚️ The document a named example loads. The subset publishes exactly one (crate::examples::demo, `ID = "demo"`),
/// whose asset IS this app's curated document; every other id — including the empty id the shell
/// sends for "the app's own default document" — opens the genesis document.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn xml_any_example_snapshot(example_id: &str) -> XmlSnapshot {
    if example_id == crate::examples::demo::ID {
        <XmlSnapshot as store::ArtifactDsl>::parse_dsl(crate::examples::demo::PRIMARY_TEXT).unwrap_or_default()
    } else {
        XmlSnapshot::default()
    }
}

/// 🌉️ Resolves the react/wgpu shells' `{action, args}` pair into this editor's typed command.
/// `ArtifactEditor::command_from_action`'s default refuses EVERY id, which is why the boot example,
/// every navbar pick and every Actions-pane row died before reaching a command.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn xml_any_command_from_action(action: &str, args: Option<&dsl::DslValue>) -> Result<XmlAnyEditorCommand, Fault> {
    if let Some(event) = semio_s_artifact_stdio_contract::editing::snapshot_edit_event_from_action(action, args)? {
        return Ok(XmlAnyEditorCommand::EditSnapshot { event });
    }
    match action {
        semio_s_artifact_stdio_contract::SET_ACTIVE_EXAMPLE_ACTION_ID => Ok(XmlAnyEditorCommand::SetActiveExample { example_id: semio_s_artifact_stdio_contract::example_id_argument(args, "") }),
        XML_ANY_KIT_ACTION_ID => Ok(XmlAnyEditorCommand::SetNode {
            node_id: semio_s_artifact_stdio_contract::window_kit_required_text_argument(args, "nodeId")?,
            revision: semio_s_artifact_stdio_contract::window_kit_required_text_argument(args, "revision")?,
            value: semio_s_artifact_stdio_contract::window_kit_required_text_argument(args, "value")?,
        }),
        other => Err(Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("stdio.xml.unhandled-action"), format!("action '{other}' is not one of this editor's declared verbs (setActiveExample, set-node)"))),
    }
}

/// 🏷️ The manifest id each command was declared under.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn xml_any_command_id(command: &XmlAnyEditorCommand) -> &'static str {
    match command {
        XmlAnyEditorCommand::SetNode { .. } => XML_ANY_KIT_ACTION_ID,
        XmlAnyEditorCommand::EditSnapshot { event } => event.action_id(),
        XmlAnyEditorCommand::SetActiveExample { .. } => semio_s_artifact_stdio_contract::SET_ACTIVE_EXAMPLE_ACTION_ID,
    }
}

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn xml_any_retained_extent(_command: &XmlAnyEditorCommand, _snapshot: &XmlSnapshot, _interaction: &protocol::InteractionState) -> Option<usize> {
    Some(1)
}

/// ✏️ The one reduction `handle` and the retained route share: the example switch hands the host
/// its document, `set-node` becomes this artifact's own mutation.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn xml_any_emit(command: &XmlAnyEditorCommand, snapshot: &XmlSnapshot, canonical_revision: Option<[u8; 32]>) -> Result<Emit<XmlMutation, NoConfigMutation, NoDraftMutation>, Fault> {
    let (node_id, revision, value) = match command {
        XmlAnyEditorCommand::SetActiveExample { example_id } => {
            return Ok(Emit { effects: vec![semio_s_artifact_stdio_contract::load_example_effect(&xml_any_example_snapshot(example_id), STDIO_XML_DOCUMENT_SCHEMA)], ..Default::default() })
        }
        XmlAnyEditorCommand::SetNode { node_id, revision, value } => (node_id, revision, value),
        XmlAnyEditorCommand::EditSnapshot { .. } => return Err(Fault::from("stdio-xml-snapshot-edit-routed-to-native-reducer")),
    };
    let current_revision = canonical_revision.map_or_else(|| semio_s_artifact_stdio_contract::window_kit_snapshot_revision(snapshot), semio_s_artifact_stdio_contract::window_kit_canonical_revision);
    if revision != &current_revision {
        return Err(Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("stdio.xml.stale-node-edit"), "the XML document changed while this node draft was open"));
    }
    if node_id == main::XML_ROOT_NODE_ID {
        let next = <XmlSnapshot as store::ArtifactDsl>::parse_dsl(value).map_err(|error| Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("stdio.xml.invalid-source"), error.to_string()))?;
        if &next == snapshot {
            return Ok(Emit::default());
        }
        return Ok(Emit { artifact_mutations: vec![XmlMutation::SetSnapshot(crate::schema::mutations::set_snapshot::SetSnapshot { snapshot: next })], ..Default::default() });
    }
    let path = decode_node_id(node_id).map_err(|detail| Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("stdio.xml.invalid-node-path"), detail))?;
    let root = snapshot.doc.root.as_ref().ok_or_else(|| Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("stdio.xml.missing-root"), "The XML document has no root node to edit."))?;
    let Some(XmlNode::Text { text }) = resolve_node(root, &path) else {
        return Err(Fault::new(semio_framework_plugin::FaultOrigin::App, semio_framework_plugin::FaultCode::new("stdio.xml.node-is-not-text"), "The addressed XML node is not a text node."));
    };
    if text == value {
        return Ok(Emit::default());
    }
    Ok(Emit { artifact_mutations: vec![XmlMutation::SetText(SetTextMutation::Apply(SetTextPayload { path: XmlNodePath(path), text: value.clone() }))], ..Default::default() })
}

#[expect(clippy::too_many_arguments, reason = "Implements the framework ArtifactCommandReducer callback signature.")]
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn xml_any_retained_reduce(
    command: &XmlAnyEditorCommand,
    snapshot: &XmlSnapshot,
    _config: &NoConfig,
    _history: &semio_framework_plugin::HistoryView,
    _interaction: &protocol::InteractionState,
    _hover: &semio_framework_plugin::app::InteractionHoverState,
    _context: Option<&semio_framework_plugin::app::ArtifactOwnedToolJobContext<EditorApp<XmlAnyEditor>>>,
    operation: &AppOperationContext,
) -> Result<Emit<XmlMutation, NoConfigMutation, NoDraftMutation>, Fault> {
    xml_any_emit(command, snapshot, Some(operation.canonical_base_revision))
}

struct XmlAnyRetainedCommandJobFactory {
    keys: Vec<ToolFactoryKey>,
}

impl XmlAnyRetainedCommandJobFactory {
    fn new(controller_id: &str) -> Self {
        Self { keys: XML_ANY_RETAINED_TOOL_IDS.iter().map(|tool_id| ToolFactoryKey::new(controller_id, *tool_id)).collect() }
    }
}

impl ToolJobFactory for XmlAnyRetainedCommandJobFactory {
    type Payload = ArtifactRetainedCommandPayload<EditorApp<XmlAnyEditor>>;
    type Job = ArtifactRetainedCommandJob<EditorApp<XmlAnyEditor>>;

    fn keys(&self) -> &[ToolFactoryKey] {
        &self.keys
    }
    fn payload_schema_id(&self) -> &str {
        XML_ANY_RETAINED_PAYLOAD_SCHEMA
    }
    fn classification(&self) -> InteractiveJobClassification {
        InteractiveJobClassification::Migrated
    }
    fn execution_contract(&self) -> ToolExecutionContract {
        xml_any_retained_contract()
    }
    fn create_job(&mut self, _operation: semio_framework_job::Operation, payload: Self::Payload) -> Result<Self::Job, ToolJobFactoryError> {
        Ok(ArtifactRetainedCommandJob::new(payload))
    }

    fn create_job_from_wire_pages_with_payload(
        &mut self,
        _operation: semio_framework_job::Operation,
        payload: Self::Payload,
        input: semio_framework_plugin::action_bus::RetainedToolWireInput,
        checkpoint: Option<semio_framework_plugin::action_bus::RetainedToolWireInput>,
    ) -> Result<Self::Job, (ToolJobFactoryError, semio_framework_plugin::action_bus::RetainedToolWireInput, Option<semio_framework_plugin::action_bus::RetainedToolWireInput>)> {
        if input.declared_bytes() > XML_ANY_RETAINED_RAW_BYTES || checkpoint.is_some() {
            return Err((ToolJobFactoryError::new("stdio xml retained command rejects oversized wire or checkpoint owner"), input, checkpoint));
        }
        Ok(ArtifactRetainedCommandJob::from_wire(payload, input))
    }
}

