/// 🧾️ Each record kind's text-grammar tag, the head `decode_op` re-prefixes onto the argument tail before `parse_op`.
const TEXT_KEYWORDS: [(&str, &str); 12] = [
    ("set-snapshot", "S"),
    ("insert-timeline", "IT"),
    ("remove-timeline", "RT"),
    ("set-timeline-name", "TN"),
    ("insert-channel", "IC"),
    ("remove-channel", "RC"),
