#[value(tag = "kind", rename_all = "camelCase")]
#[derive(Default)]
pub enum AnimTargetProperty {
    #[default]
    Translation,
    Rotation,
    Scale,
    Weights,
    Custom {
        name: String,
    },
}

/// 🎯️ A channel's animated node + which of its properties is driven.
