//! 🚪️ curation <- json — foreign `Deserializer<CurationSnapshot>` (ticket 26/08/17/CLEAN-ARTIFACT-
//! STANDARD-SUBSET-MECHANISM design.md §3). Bridges via json's own text codec (`parse_json_text`)
//! then a genuine `pack::JsonValue -> DslValue -> CurationSnapshot` structural deserialize (ticket
//! 26/09/01/RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS — no `serde_json` left in
//! this hop) — a real, lossless round trip of the same type's own value shape, so this hop is
//! `IoFidelity::Exact` (unlike the sibling zip/png/stl/obj leaves, which are pre-existing
//! non-functional stubs — see this subset's `📓️w4-sourcing-report.md` `## openQuestions`).
//!
//! `JsonSnapshot::value` is stdio's own `JsonValue` (key-order/lexeme-preserving RFC8259 model,
//! never `serde_json::Value` — see that snapshot module's own doc). Bridges via json's own text
//! codec rather than a per-leaf structural converter, mirroring `s/plugin/lowpoly`'s identical leaf.
use crate::CurationSnapshot;
use dsl::FromValue;
use crate::SOURCING_CURATION_SCHEMA;
use semio_framework::io::io_mechanism::Deserializer;
use semio_framework::io_schema::{Dialect, IoError, IoFidelity, IoOutcome, IoPayload, IoResult};
use semio_framework_plugin::{StandardId, SubsetId};
use semio_s_artifact_stdio_json::schema::snapshot::parse_json_text;
use semio_s_artifact_stdio_json::JsonSnapshot;

pub const JSON_DIALECT: Dialect = Dialect { artifact_kind: "s.stdio.json", standard: StandardId("rfc8259"), subset: SubsetId::ANY };

pub fn deserialize(from: &JsonSnapshot) -> Result<CurationSnapshot, semio_framework_diagnostic::TextError> {
    let _ = SOURCING_CURATION_SCHEMA;
    CurationSnapshot::from_value(dsl::json::to_dsl_value(&from.to_pack_value())).map_err(|e| semio_framework_diagnostic::TextError::new(format!("curation<-json: {e}"), semio_framework_diagnostic::TextSpan::at(1, 1)))
}

pub fn deserialize_bytes(bytes: &[u8]) -> Result<CurationSnapshot, semio_framework_diagnostic::TextError> {
    let text = std::str::from_utf8(bytes).map_err(|e| semio_framework_diagnostic::TextError::new(e.to_string(), semio_framework_diagnostic::TextSpan::at(1, 1)))?;
    let value = parse_json_text(text)?;
    deserialize(&JsonSnapshot::from_value(value))
}

pub struct JsonIntoCuration;

impl Deserializer<CurationSnapshot> for JsonIntoCuration {
    const FROM: Dialect = JSON_DIALECT;
    const FIDELITY: IoFidelity = IoFidelity::Exact;
    async fn deserialize(payload: &IoPayload) -> IoResult<CurationSnapshot> {
        let IoPayload::Text(text) = payload else {
            return Err(IoError { message: "JsonIntoCuration: expected a text json payload".to_string(), diagnostics: Vec::new() });
        };
        deserialize_bytes(text.as_bytes()).map(IoOutcome::clean).map_err(|error| IoError { message: format!("JsonIntoCuration: {error}"), diagnostics: Vec::new() })
    }
}

//! 🧬️ SemioDrawingSnapshot — canvas + name-keyed styles + ordered layers, each a recursive
//! `DrawNode`{Path{segments}/Text/Group{transform,children}/Image} scene graph — from svg;
//! replaces DwgDrawing-as-neutral. Real, complete-per-spec-row shape (master plan "drawing" row):
//! no `serde_json::Value`, no bare tuples/nested fixed arrays (geometry fields reuse
//! `engine::geometry`'s named structs throughout).

use crate::standards::v1::subsets::base::schema::geometry::native::{NativeF64,NativeF32};
use crate::standards::v1::subsets::base::schema::geometry::{SemioPoint3, SemioQuaternion, SemioRgba, SemioTransform};
use crate::standards::v1::subsets::base::schema::triples::{split_top_level, strip_brackets};
use framework_schema::ArtifactSchema;

//#region 🔖️PathSegment
/// ✏️ A single SVG-style path command — the honest, complete production set for `Path.segments`
/// (no `*OCTET`/size-eos catch-all: every field a real drawn quantity).
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue)]
#[value(tag = "kind", rename_all = "camelCase", rename_all_fields = "camelCase")]
pub enum PathSegment {
    MoveTo {
        to: SemioPoint2,
    },
    LineTo {
        to: SemioPoint2,
    },
    CubicTo {
        c1: SemioPoint2,
        c2: SemioPoint2,
        to: SemioPoint2,
    },
    QuadTo {
        c: SemioPoint2,
        to: SemioPoint2,
    },
    /// 🌙️ Elliptical arc, SVG `A rx ry x-rotation large-arc sweep x y` shape.
    ArcTo {
        rx: f64,
        ry: f64,
        x_rotation: f64,
        large_arc: bool,
        sweep: bool,
        to: SemioPoint2,
    },
    Close,
}
//#endregion 🔖️PathSegment

//#region 🔖️DrawNode
/// 🖍️ Owned by the `drawing` subset: the recursive scene-graph node, matching svg's
/// `SvgNodeDiff` recursive-diff template per the master plan. `style` fields are a referential
/// `Option<String>` into `SemioDrawingSnapshot.styles` by name (checked by `SemioDrawingValidator`
/// — dangling references are a real referential-invariant breach, not silently tolerated).
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue)]
#[value(tag = "kind", rename_all = "camelCase")]
pub enum DrawNode {
    Path {
        segments: Vec<PathSegment>,
        #[value(default, skip_serializing_if = "Option::is_none")]
        style: Option<String>,
    },
    Text {
        value: String,
        at: SemioPoint2,
        #[value(default, skip_serializing_if = "Option::is_none")]
        style: Option<String>,
    },
    Group {
        transform: SemioTransform,
        #[value(default)]
        children: Vec<DrawNode>,
    },
    /// 🖼️ Raster payload embedded verbatim (typed raw retention — real bytes, not a lie).
    Image { at: SemioPoint2, width: f64, height: f64, mime: String, bytes: Vec<u8> },
}

impl Default for DrawNode {
    fn default() -> Self {
        DrawNode::Group { transform: SemioTransform::identity(), children: Vec::new() }
    }
}
//#endregion 🔖️DrawNode

//#region 🔖️Style
/// 🎨️ A named presentation style, referenced by `DrawNode::Path`/`Text.style`. Name-keyed
/// (`NamedTripleDiff<String, DrawStyleDiff, DrawStyle>` in the diff facet).
/// 🩹 `Default` derived (not just decoration) — required transitively as the `T` of
/// `triples::NamedTripleDiff<String, DrawStyleDiff, DrawStyle>`'s generated `Deserialize` impl
/// (serde-derive's bound inference for `#[value(default)]` fields on a generic container reaches
/// every type parameter, not just the immediately-defaulted field's own type).
#[derive(Clone, Debug, Default, PartialEq, value_derive::ToValue, value_derive::FromValue)]
#[value(rename_all = "camelCase")]
pub struct DrawStyle {
    pub name: String,
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub fill: Option<SemioRgba>,
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub stroke: Option<SemioRgba>,
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub stroke_width: Option<f64>,
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub opacity: Option<f32>,
}
//#endregion 🔖️Style

//#region 🔖️Layer
/// 🗂️ One ordered layer (index-keyed z-order, `IndexedTripleDiff<DrawLayerDiff, DrawLayer>` in
/// the diff facet — mirrors gif-frame ordering precedent).
/// 🩹 `Default` derived for the same reason as `DrawStyle` above (needed as the `T` of
/// `triples::IndexedTripleDiff<DrawLayerDiff, DrawLayer>`).
#[derive(Clone, Debug, Default, PartialEq, value_derive::ToValue, value_derive::FromValue)]
#[value(rename_all = "camelCase")]
pub struct DrawLayer {
    pub id: String,
    pub name: String,
    pub visible: bool,
    #[value(serialize_controlled_with="component::nodes::encode_node",deserialize_controlled_with="component::nodes::decode_node",retire_with="component::nodes::retire_node")]
    pub root: DrawNode,
}
//#endregion 🔖️Layer

